/* ---------- State ---------- */
let state,storageAvailable=true;
let route='overview',sub='',filter='Tümü',query='',lastFocus=null,notifOpen=false,tender=null,mcpDraftTools=null;const ui={};
function loadState(){try{const parsed=JSON.parse(localStorage.getItem(KEY));state=parsed&&parsed.version===VERSION&&['projects','clients','tasks','team','approvals','invoices','audit','twins','notifications','mails','brandMemory','employees','candidates'].every(k=>Array.isArray(parsed[k]))&&parsed.board&&parsed.settings&&parsed.profiles&&parsed.session?parsed:seed();if(parsed&&parsed.version!==VERSION)console.info('JS Ecosystem: eski sürüm verisi sıfırlandı (v'+parsed.version+' → v'+VERSION+').')}catch{state=seed();storageAvailable=false}}
const $=s=>document.querySelector(s);
const client=id=>state.clients.find(c=>c.id===id)?.name||'Müşteri';
const brand=id=>state.clients.find(c=>c.id===id);
const project=id=>state.projects.find(p=>p.id===id);
const person=id=>state.team.find(p=>p.id===id)?.name||state.profiles[id]?.name||id;
const money=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format(n||0);
const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2}).format(n);
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('tr-TR',{day:'2-digit',month:'short'}):'—';
const now=()=>new Date().toLocaleString('tr-TR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
const daysFromToday=s=>Math.round((new Date(s+'T12:00:00')-new Date(TODAY+'T12:00:00'))/86400000);
const progress=p=>{let ts=state.tasks.filter(t=>t.project===p.id);return p.status==='Tamamlandı'?100:ts.length?Math.round(ts.filter(t=>t.done).length/ts.length*100):0};
const getPath=(o,path)=>path.split('.').reduce((a,k)=>a?.[k],o);
const setPath=(o,path,v)=>{const ks=path.split('.');let cur=o;ks.slice(0,-1).forEach(k=>{if(typeof cur[k]!=='object'||cur[k]===null)cur[k]={};cur=cur[k]});cur[ks.at(-1)]=v};
const uid=p=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,5);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageAvailable=false;toast('Tarayıcı depolaması kullanılamıyor; değişiklikler bu oturumda tutuluyor.')}}
function log(text){state.audit.unshift({text,at:new Date().toLocaleString('tr-TR'),who:account().name,role:role()});state.audit=state.audit.slice(0,300);save()}
function emit(type,aggregate,actor,processed=true){state.events.unshift({id:'e'+Date.now()+Math.random().toString(36).slice(2,5),type,aggregate,actor:actor||('user:'+account().person),at:now(),processed});state.events=state.events.slice(0,120)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
const badge=(text,cls)=>{const t=String(text);const k=cls||(['Bekliyor','Yüksek','Revizyon','AMBER','MED','ERTELE','Çalışıyor','Orta','Potansiyel','Devir','Riskli','Görüşme','Teklif','İç revize','Onay','İmza bekliyor','Taslak','Zamanlandı','Devam ediyor','Case','Müşteri onayı','Müşteri kararı','Kapsam dışı','Bütçe','Vadesi yaklaşıyor','Teyit bekliyor','Kısmi'].includes(t)?'warn':['Onaylandı','Tamamlandı','Ödendi','Bağlı','Aktif','Başarılı','GREEN','HIGH','EVET','Düşük','Müsait','Kazanıldı','Yayında','Teslim','İmzalandı','Çözüldü','Açık','Sağlıklı','Senkron','İzinli (onaylı)','Dahil','Yayınlandı','Gönderildi','Tam'].includes(t)?'success':['Hata','RED','HAYIR','Kritik','İptal edildi','Gecikmiş','Kaybedildi','Reddedildi','Şüpheli','Süresi doldu','Kapalı','Ayrıldı','Acil','Eksik','Yetki değişikliği'].includes(t)?'danger':['Planlama','Bağlı değil','Devre dışı','LOW','Rol','Odakta','Toplantıda','İzinde','Arşiv','Yeni','Brief','Kapsam','Plan','Üretim','Fikir','Metin','Görsel','İç onay','Dahili','Başvuru','Pasif','İçerik','Planlandı'].includes(t)?'neutral':'');return `<span class="badge ${k}">${esc(t)}</span>`};
const btn=(text,action,cls='',icon='arrow',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${ic(icon)}<span>${text}</span></button>`;
const sw=(path,checked,label,extra='')=>`<button class="switch" role="switch" aria-checked="${!!checked}" aria-label="${esc(label)}" data-action="toggle" data-path="${path}" ${extra}></button>`;
const sel=(path,opts,val,extra='')=>`<select data-bind="${path}" ${extra}>${opts.map(o=>`<option ${o==val?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
const chips=(path,items,placeholder='Ekle ve Enter')=>`<div class="chip-row">${items.map(x=>`<span class="chip">${esc(x)}<button data-action="chip-remove" data-path="${path}" data-id="${esc(x)}" aria-label="${esc(x)} kaldır">${ic('close')}</button></span>`).join('')}<input class="chip-input" data-chip-add="${path}" placeholder="${placeholder}" aria-label="${placeholder}"></div>`;
const tbl=(cols,rows,label='Tablo',caption='')=>`<div class="panel table-wrap" tabindex="0" role="region" aria-label="${esc(label)}"><table>${caption?`<caption>${caption}</caption>`:''}<thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${cols.length}" class="empty">Kayıt yok.</td></tr>`}</tbody></table></div>`;
const meter=(pct,cls='')=>`<div class="progress ${cls} ${pct>100?'over':''}" role="img" aria-label="Yüzde ${Math.round(pct)}"><span style="width:${Math.min(100,pct)}%"></span></div>`;
const kv=(pairs)=>`<dl class="kv">${pairs.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;
const option=(v,l,cur)=>`<option value="${esc(v)}" ${v===cur?'selected':''}>${esc(l)}</option>`;
const profile=()=>{const id=state.viewAs||'BY';if(!state.profiles[id]){const t=state.team.find(x=>x.id===id),tw=state.twins.find(x=>x.id===id);state.profiles[id]={id,name:t?.name||id,role:t?.role||'Ekip üyesi',status:'Müsait',statusMsg:'',brands:[],taskTypes:[],capacity:40,approach:'',comms:'',twin:{velocity:tw?.velocity||[],bias:tw?.bias||'—',confidence:tw?.confidence||'LOW',canBid:true,dailyDraft:false,shareScreen:false,optout:[],approvedAt:tw?.approvedAt||'—'},integrations:{google:true,trello:true,slack:true,kolayik:false},notif:{mentions:true,digest:false,board:false,quiet:true},security:{sessions:[{id:'s1',device:'Tarayıcı oturumu',place:'Ankara',last:'Şimdi',current:true}],mfa:false,passwordless:false}}}return state.profiles[id]};
const pendingDecisions=()=>state.board.decisions.filter(d=>d.status==='Bekliyor').length;
const unread=()=>state.notifications.filter(n=>!n.read).length;
const costToday=()=>state.runs.filter(r=>r.at.startsWith('14.10')||r.at.startsWith(new Date().toLocaleDateString('tr-TR',{day:'2-digit',month:'2-digit'}))).reduce((s,r)=>s+r.cost,0);
const initials=n=>String(n||'').split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('').toLocaleUpperCase('tr');

/* ---------- Role & scope ---------- */
const account=()=>accounts.find(a=>a.id===state.session.account)||accounts[0];
const role=()=>account().role;
const isClient=()=>role()==='client';
const clientBrands=()=>account().brands||[];
const can=m=>state.flags[m]!==false&&(state.access[role()]||[]).includes(m);
const visibleModules=()=>moduleCatalog.filter(m=>can(m.id));
const inScope=id=>!isClient()||clientBrands().includes(id);
const myProjects=()=>state.projects.filter(p=>inScope(p.client)&&(!isClient()||p.client_visible!==false));
const myTasks=()=>state.tasks.filter(t=>{const p=project(t.project);return p?inScope(p.client)&&(!isClient()||t.client_visible):!isClient()});
const navGroups=()=>['main','work','creative','people','intel','manage'].map(g=>[groupLabels[g],visibleModules().filter(m=>m.group===g).map(m=>[m.id,m.name])]).filter(g=>g[1].length);
const nav=()=>moduleCatalog.map(m=>[m.id,m.name]);
const navCount=id=>id==='approvals'?state.approvals.filter(a=>a.status==='Bekliyor'&&(!isClient()||a.kind==='Müşteri kararı')).length:id==='board'?pendingDecisions():id==='inbox'?(state.mails||[]).filter(m=>m.status==='Yeni').length:0;

/* ---------- Shell ---------- */
function render(){const focused=document.activeElement;const focusKey=focused?.dataset?{action:focused.dataset.action,id:focused.dataset.id,filter:focused.dataset.filter}:{};document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.toggle('compact',state.compact);
if(!state.session.loggedIn){document.title='Demo giriş — JS Ecosystem';$('#app').innerHTML=loginView();return}
const mod=moduleCatalog.find(m=>m.id===route);const name=mod?.name||'Genel Bakış';const subName=subTabs[route]?.find(s=>s[0]===sub)?.[1];document.title=`${name}${subName?' · '+subName:''} — JS Ecosystem`;const me=account();const orgName=state.session.org==='edit'?'Edit Culture & Events':'Jobs Studio';
$('#app').innerHTML=`<aside class="sidebar" aria-label="Ana gezinme"><a href="#overview" aria-label="JS Ecosystem ana sayfa"><img class="logo" src="assets/jobs-logo-light.svg" alt="Jobs Studio"></a><a class="wordmark" href="#overview">JS Ecosystem<b>.</b></a><div class="workspace"><div class="workspace-mark">${state.session.org==='edit'?'EC':'JS'}</div><div>${esc(orgName)} · Ankara<small>${roleLabel[role()]} görünümü</small></div></div><nav>${navGroups().map(([label,items])=>`<div class="nav-label">${label}</div>${items.map(navLink).join('')}`).join('')}</nav><div class="sidebar-foot"><a class="identity" href="#profile" aria-label="Profilim"><div class="avatar">${initials(me.name)}</div><div>${esc(me.name)}<small>${esc(me.title)}</small></div></a></div></aside><div class="shell"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Menüyü aç" aria-expanded="false">${ic('menu')}</button><div class="breadcrumb">${esc(orgName)} ${ic('chevron')} <strong>${name}</strong>${subName?` ${ic('chevron')} <span>${subName}</span>`:''}</div><div class="top-actions"><button class="search-trigger" data-action="command" aria-label="Komut menüsünü aç">${ic('search')}<span>Her yerde ara</span><kbd>⌘ K</kbd></button><button class="role-chip" data-action="switch-role" aria-label="Rolü değiştir · şu an ${roleLabel[role()]}"><span class="dot"></span><span>${roleLabel[role()]}</span><small>Rolü değiştir</small></button><span class="top-year"><i class="demo-dot"></i>v0.5 · prototip</span><div class="notif-wrap"><button class="icon-button bell" data-action="notif" aria-label="Bildirimler (${unread()} okunmamış)" aria-expanded="${notifOpen}">${ic('bell')}${unread()?`<span class="count-dot">${unread()}</span>`:''}</button>${notifOpen?notifMenu():''}</div><button class="icon-button" data-action="theme" aria-label="${state.theme==='dark'?'Açık':'Koyu'} temaya geç">${ic('sun')}</button><a class="avatar" href="#profile" aria-label="Profilim" style="text-decoration:none">${initials(me.name)}</a></div></header><main class="main page-enter" id="main" tabindex="-1">${can(route)?views[route]():forbidden()}<footer class="footer"><span>JS Ecosystem · Jobs Studio © 2026 · Prototip, tüm veriler örnektir. <a href="#admin/security">İşlem kaydı</a></span><span>Demo tarihi 14 Ekim 2026 · ${storageAvailable?'Yerel kayıt açık':'Yerel kayıt kapalı'} · Demo giriş — kimlik doğrulama değildir</span></footer></main>${tabbar()}</div>`;
if(focusKey.action&&!$('#modal').open){const target=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focusKey.action&&el.dataset.id===focusKey.id&&el.dataset.filter===focusKey.filter);target?.focus({preventScroll:true})}}
function forbidden(){return head('ERİŞİM','Bu modül bu rolde görünmüyor.','Yetki; organization + product + resource + action + scope bileşimidir. Modülü Ürünler & Paketler’den veya Admin → Feature Flags’ten açabilirsin.')+`<div class="panel" style="padding:24px"><p>Rol: <strong>${roleLabel[role()]}</strong> · Modül: <code class="mono">${esc(route)}</code></p><div class="form-actions" style="justify-content:start">${btn('Genel Bakış’a dön','goto','primary','arrow','data-id="overview"')}${btn('Rolü değiştir','switch-role','','user')}</div></div>`}
function tabbar(){const items=[['overview','Ana Sayfa','dashboard'],['tasks','Görevler','tasks'],['inbox','Gelen Kutusu','inbox'],['apps','Uygulamalar','apps'],['profile','Hesabım','profile']].map(([id,l,i])=>can(id)||id==='apps'?[id,l,i]:id==='inbox'?['approvals','Onaylar','approvals']:[id,l,i]);return `<nav class="tabbar" aria-label="Mobil gezinme">${items.map(([id,l,i])=>`<a href="#${id}" class="${route===id?'on':''}" ${route===id?'aria-current="page"':''}>${ic(i)}<span>${l}</span></a>`).join('')}</nav>`}
function navLink([id,label]){const count=navCount(id);return `<a href="#${id}" class="nav-item ${route===id?'active':''}" ${route===id?'aria-current="page"':''} title="${label}" style="text-decoration:none">${ic(moduleCatalog.find(m=>m.id===id)?.icon||id)}<span>${label}</span>${count?`<span class="count">${count}</span>`:''}</a>`}
function notifMenu(){return `<div class="notif-menu" role="dialog" aria-label="Bildirimler"><header><span>Bildirimler</span><button class="text-button" data-action="notif-read-all">Tümünü okundu say</button></header>${state.notifications.slice(0,6).map(n=>`<button class="notif-item ${n.read?'read':''}" data-action="notif-open" data-id="${n.id}"><span class="ndot"></span><span>${esc(n.text)}<small>${esc(n.time)}</small></span></button>`).join('')||'<p class="empty" style="padding:24px">Bildirim yok.</p>'}</div>`}
function loginView(){return `<div class="login"><div class="login-card"><img class="logo" src="assets/jobs-logo-light.svg" alt="Jobs Studio"><div class="eyebrow">JS ECOSYSTEM · DEMO GİRİŞ</div><h1>Bir rol seç, ajansı o gözle gör.</h1><p class="muted">Demo giriş — kimlik doğrulama değildir. Rol yalnızca menü, veri kapsamı ve ekran içeriğini değiştirir; sunucu, şifre ve gerçek yetki denetimi yoktur.</p><div class="login-roles">${accounts.map(a=>`<button class="role-card" data-action="login" data-id="${a.id}"><span class="avatar">${initials(a.name)}</span><span class="rc-text"><strong>${esc(a.name)}</strong><small>${esc(a.title)}</small><small class="muted">${esc(a.hint)}</small></span>${badge(roleLabel[a.role],a.role==='client'?'warn':a.role==='owner'?'ai':'neutral')}${ic('chevron')}</button>`).join('')}</div><p class="small muted login-foot">Demo tarihi 14 Ekim 2026 · Tüm kayıtlar kurgusaldır · 25 modül · 8 demo hesap · JS People HRIS + Kolay İK aktarım merkezi</p></div></div>`}
function head(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action?`<div class="page-actions">${action}</div>`:''}</div>`}
function metric(label,value,note,icon){return `<div class="metric"><div class="metric-top">${label}${ic(icon)}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`}
function subnav(){return `<div class="subnav" role="tablist" aria-label="Bölümler">${subTabs[route].map(([id,label])=>`<button role="tab" class="${sub===id?'active':''}" aria-selected="${sub===id}" data-action="sub" data-id="${id}"><span class="lbl">${label}</span></button>`).join('')}</div>`}
function projectRow(p){let pr=progress(p);return `<div class="project-row"><div class="project-symbol">${esc(client(p.client)[0])}</div><div class="project-info"><button data-action="project" data-id="${p.id}">${esc(p.name)}</button><small>${esc(client(p.client))} · ${esc(p.type)}</small></div>${badge(p.status)}<div class="project-progress"><small><span>İlerleme</span><span>%${pr}</span></small><div class="progress" role="img" aria-label="Yüzde ${pr} tamamlandı"><span style="width:${pr}%"></span></div></div><button class="icon-button" data-action="project" data-id="${p.id}" aria-label="${esc(p.name)} projesini aç">${ic('chevron')}</button></div>`}
function taskRow(t){return `<div class="task-row ${t.done?'done':''}"><button class="check ${t.done?'done':''}" data-action="task" data-id="${t.id}" aria-label="${esc(t.name)}: ${t.done?'yeniden aç':'tamamla'}" aria-pressed="${t.done}">${t.done?ic('check'):''}</button><div class="task-text"><button class="task-open" data-action="task-open" data-id="${t.id}"><strong>${esc(t.name)}</strong></button><small>${esc(project(t.project)?.name||'Proje')} · ${esc(t.date)} · ${esc(t.stage||'')}</small></div><span class="avatar" title="${esc(person(t.owner))}">${esc(t.owner)}</span></div>`}
function tabs(items){return `<div class="tabs" aria-label="Görünümü filtrele">${items.map(x=>`<button class="tab ${filter===x?'active':''}" data-action="filter" data-filter="${x}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div>`}
function kanban(cols,items,card,moveAction,keyFn){return `<div class="kanban" role="list">${cols.map((c,ci)=>{const its=items.filter(i=>keyFn(i)===c);return `<div class="kcol" role="listitem"><div class="kcol-head"><span>${esc(c)}</span><span class="count">${its.length}</span></div>${its.map(i=>`<article class="kcard">${card(i)}<div class="kmove">${ci>0?`<button class="icon-button sm" data-action="${moveAction}" data-id="${i.id}" data-to="${esc(cols[ci-1])}" aria-label="${esc(cols[ci-1])} kolonuna taşı">${ic('left')}</button>`:''}${ci<cols.length-1?`<button class="icon-button sm" data-action="${moveAction}" data-id="${i.id}" data-to="${esc(cols[ci+1])}" aria-label="${esc(cols[ci+1])} kolonuna taşı">${ic('right')}</button>`:''}</div></article>`).join('')||'<p class="empty small">—</p>'}</div>`}).join('')}</div>`}
function svgBars(data,opts={}){const max=Math.max(...data.map(d=>d[1]),1);const w=opts.w||420,h=opts.h||160,pad=24,bw=(w-pad)/data.length;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(opts.label||'Çubuk grafik')}"><line x1="${pad}" y1="${h-24}" x2="${w}" y2="${h-24}" class="axis"/>${data.map((d,i)=>{const bh=Math.round((h-40)*d[1]/max);const x=pad+i*bw+bw*.15;return `<rect x="${x}" y="${h-24-bh}" width="${bw*.7}" height="${bh}" rx="3" class="bar ${d[2]||''}"><title>${esc(d[0])}: ${d[1]}</title></rect><text x="${x+bw*.35}" y="${h-8}" class="lbl" text-anchor="middle">${esc(d[0])}</text><text x="${x+bw*.35}" y="${h-28-bh}" class="val" text-anchor="middle">${d[1]}${opts.unit||''}</text>`}).join('')}</svg>`}
function svgLine(series,opts={}){const w=opts.w||420,h=opts.h||160,pad=24;const all=series.flatMap(s=>s.data);const max=Math.max(...all,1),min=opts.min??0;const n=series[0].data.length;const x=i=>pad+i*((w-pad-8)/(n-1));const y=v=>h-24-((v-min)/(max-min||1))*(h-40);return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(opts.label||'Çizgi grafik')}"><line x1="${pad}" y1="${h-24}" x2="${w}" y2="${h-24}" class="axis"/>${series.map((s,si)=>`<polyline class="line s${si}" points="${s.data.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}"/>${s.data.map((v,i)=>`<circle class="pt s${si}" cx="${x(i)}" cy="${y(v)}" r="3"><title>${esc(s.name)} · ${esc(opts.labels?.[i]||i)}: ${v}</title></circle>`).join('')}`).join('')}${(opts.labels||[]).map((l,i)=>`<text x="${x(i)}" y="${h-8}" class="lbl" text-anchor="middle">${esc(l)}</text>`).join('')}</svg>`}
const legend=names=>`<div class="legend">${names.map((n,i)=>`<span><i class="s${i}"></i>${esc(n)}</span>`).join('')}</div>`;

/* ---------- Legacy views: Yönetim Kurulu, Dijital İkizler, Otomasyon, JS Connect, Ayarlar, Profilim ---------- */
/* ---------- Yönetim Kurulu ---------- */
function board(){const b=state.board;const ds=b.decisions.filter(d=>filter==='Tümü'?true:filter==='Bekleyen'?d.status==='Bekliyor':d.status!=='Bekliyor');return head('ZEKÂ · YÖNETİM KURULU','Dokuz ajan, tek masa.','Haftalık kurul Cuma 17:00. Seviye 0 kararlar otomatik uygulanır; Seviye 1–2 kurucuya düşer. Her karar işlem kaydına yazılır.',btn('Kurulu şimdi topla','board-run','primary','spark'))+`<section class="health-grid" aria-label="Ajan sağlık durumu">${b.agents.map(a=>`<button class="health ${a.health}" data-action="agent" data-id="${a.id}" aria-label="${a.role}: ${a.health}"><span class="role"><span class="dot"></span>${a.role}${state.settings.ai.agents[a.id]===false?' <span class="badge neutral">Kapalı</span>':''}</span><small>${esc(a.headline)}</small></button>`).join('')}</section><section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>Bekleyen kararlar <span class="muted small">${pendingDecisions()}</span></h2>${tabs(['Tümü','Bekleyen','Karara bağlanan'])}</div><div class="panel-body"><div class="decision-grid">${ds.map(decisionCard).join('')||'<p class="empty" style="grid-column:1/-1">Bu görünümde karar yok.</p>'}</div></div></section><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Son kurul · ${esc(b.lastMeeting.date)}</h2>${badge(`${b.lastMeeting.auto} otomatik · ${b.lastMeeting.founder} kurucuya`,'neutral')}</div><div class="panel-body"><ul class="meeting-list">${b.lastMeeting.notes.map(n=>`<li>${ic('check')}<span>${esc(n)}</span></li>`).join('')}</ul></div></div><div class="kpi-strip">${metric('Runway',`${b.kpi.runway} <small>gün</small>`,'CFO · nakit / aylık sabit gider','finance')}${metric('Seviye 0 oranı',`%${b.kpi.level0}`,'Otomatik uygulanan karar payı (4 hafta)','automation')}${metric('Kurucuya giden',`${b.kpi.toFounder} <small>/ hafta</small>`,'Hedef ≤ 3 · insan kararı korunur','profile')}</div></section>`}
function decisionCard(d){const done=d.status!=='Bekliyor';return `<article class="decision ${done?'done':''}" aria-label="${d.id}"><div class="meta"><code>${d.id}</code>${badge(d.agent,'ai')}${badge(`Seviye ${d.level}`,'neutral')}${done?badge(d.status):''}</div><h3>${esc(d.title)}</h3><dl><dt>Aksiyon</dt><dd>${esc(d.action)}</dd><dt>Neden şimdi</dt><dd>${esc(d.why)}</dd><dt>Risk</dt><dd>${esc(d.risk)}</dd><dt>Önerilen</dt><dd>${badge(d.suggested)}${d.decidedAt?` <span class="muted small">Karar: ${esc(d.decidedAt)}</span>`:''}</dd></dl><div class="actions">${done?btn('Geri al','decide','','refresh',`data-id="${d.id}" data-value="Bekliyor"`):`${btn('Evet','decide','yes','check',`data-id="${d.id}" data-value="EVET"`)}${btn('Hayır','decide','no','close',`data-id="${d.id}" data-value="HAYIR"`)}${btn('Ertele','decide','','clock',`data-id="${d.id}" data-value="ERTELE"`)}`}</div></article>`}
function agentDetail(id){const a=state.board.agents.find(x=>x.id===id);if(!a)return;const ds=state.board.decisions.filter(d=>d.agent===a.role);const on=state.settings.ai.agents[id]!==false;openDialog(`${a.role} ajanı`,`<div class="dialog-body"><div class="actions">${badge(a.health)}${badge(on?'Aktif':'Devre dışı')}${badge(`Model: ${state.settings.ai.model}`,'neutral')}</div><p style="margin-top:14px">${esc(a.headline)}</p><h3>Bu ajanın karar önerileri</h3>${ds.map(d=>`<p><code class="mono">${d.id}</code> · ${esc(d.title)} ${badge(d.status)}</p>`).join('')||'<p>Bekleyen öneri yok.</p>'}<h3>Yetki sınırı</h3><p>Seviye 0 (≤ ${money(state.settings.structure.level0Max)}) kararları otomatik uygular; üstü kurucuya gider. Yalnızca Bağlantılar’da izin verilen MCP araçlarını çağırabilir.</p><div class="form-actions">${btn(on?'Ajanı duraklat':'Ajanı etkinleştir','agent-toggle',on?'':'primary',on?'clock':'play',`data-id="${id}"`)}</div></div>`)}

/* ---------- Dijital İkizler ---------- */
const twinPlanned=t=>t.kind==='Kişi'?(state.team.find(x=>x.id===t.id)?.hours??0):(t.planned??0);
function twins(){return head('ZEKÂ · DİJİTAL İKİZLER','Her kişinin bir ikizi var.','İkiz; kişinin hız, tercih ve kapasitesini öğrenir, onun adına teklif verir. Karar her zaman insanda kalır.',btn('Yeni iş ihalesi','tender','primary','plus'))+`<div class="banner">${ic('info')}<span>Kişi ikizleri yalnızca kişinin onayladığı profil verisini kullanır (Profilim → Dijital ikizim). Rol ikizleri kişiye bağlı değildir; devir ikizi ayrılan kişinin bilgisini yeni sahibine aktarır.</span></div><section class="metrics" aria-label="İkiz özeti">${metric('Aktif ikiz',state.twins.filter(t=>!t.paused).length,`${state.twins.length} ikiz tanımlı`,'twins')}${metric('Boş kapasite',`${state.twins.filter(t=>t.kind==='Kişi').reduce((s,t)=>s+Math.max(0,t.capacity-twinPlanned(t)),0)} <small>saat</small>`,'Bu hafta · kişi ikizleri','clock')}${metric('Son ihale','TN-118','Clayton teklifi · 3 teklif · plan onaylandı','spark')}${metric('Onaylı profil',state.twins.filter(t=>t.approvedAt!=='—').length,'Profil onayı olmadan ikiz teklif vermez','check')}</section><section class="panel"><div class="panel-header"><h2>İkizler</h2><span class="small muted">Kapasite çubuğu = planlanan / haftalık saat</span></div><div class="panel-body">${state.twins.map(t=>{const pl=twinPlanned(t),free=t.capacity-pl,pct=Math.min(100,Math.round(pl/t.capacity*100));return `<div class="twin-row"><div class="name-cell"><span class="avatar">${initials(t.name)}</span><div><strong style="font-weight:500">${esc(t.name)}</strong>${t.paused?` ${badge('Duraklatıldı','neutral')}`:''}<small class="muted" style="display:block">${esc(t.role)}${t.lastDay?` · son gün ${t.lastDay}`:''}</small></div></div><div class="kind">${badge(t.kind,t.kind==='Kişi'?'':t.kind==='Rol'?'ai':'warn')}</div><div class="cap"><small><span>${pl} / ${t.capacity} saat</span><span>${free<0?`${-free} saat fazla`:`${free} saat boş`}</span></small><div class="progress ${free<0?'over':''}"><span style="width:${pct}%"></span></div></div><div class="conf">${badge(t.confidence)}</div><div class="approved muted">Onay: ${esc(t.approvedAt)}</div><button class="icon-button" data-action="twin" data-id="${t.id}" aria-label="${esc(t.name)} ikizini aç">${ic('chevron')}</button></div>`}).join('')}</div></section>`}
function twinDetail(id){const t=state.twins.find(x=>x.id===id);if(!t)return;openDialog(`${esc(t.name)} · ikiz`,`<div class="dialog-body"><div class="actions">${badge(t.kind,t.kind==='Kişi'?'':'ai')}${badge(t.confidence)}${badge(t.paused?'Duraklatıldı':'Aktif')}</div><p style="margin-top:14px">${esc(t.role)} · Haftalık ${twinPlanned(t)} / ${t.capacity} saat · Profil onayı: ${esc(t.approvedAt)}</p><h3>Görev türüne göre hız</h3><table class="vel-table"><thead><tr><th>GÖREV TÜRÜ</th><th>ORTALAMA SAAT</th></tr></thead><tbody>${t.velocity.map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v}</td></tr>`).join('')}</tbody></table><p style="margin-top:14px">Tahmin sapması: <strong>${esc(t.bias)}</strong></p>${t.kind==='Devir'?`<div class="banner">${ic('info')}<span>Devir ikizi: ${esc(t.name)} ${t.lastDay} tarihinde ayrılıyor. İkiz; müşteri yazışmaları, açık işler ve tercihleri yeni sahibine özet olarak aktarır, ondan sonra silinir.</span></div>`:''}<div class="form-actions">${btn(t.paused?'İkizi etkinleştir':'İkizi duraklat','twin-toggle',t.paused?'primary':'','clock',`data-id="${id}"`)}${btn('İhale aç','tender','primary','plus')}</div></div>`)}
function tenderDialog(){tender=null;openDialog('Yeni iş ihalesi',`<form class="dialog-body" id="tender-form"><p>Briefi yaz; eşleşen ikizler saat, kapasite ve riskle teklif verir. Hiçbir şey sen planı onaylamadan oluşmaz.</p><div class="form-grid"><label class="form-field full">Brief<textarea name="brief" required maxlength="800" placeholder="Örn. Wellana için 12 postluk sosyal metin seti ve 3 görsel; 1 kısa reels kurgusu."></textarea></label><label class="form-field">Proje<select name="project">${state.projects.filter(p=>p.status!=='Tamamlandı').map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label class="form-field">Termin<input type="date" name="due" value="2026-10-23" required></label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Teklifleri topla ${ic('spark')}</button></div></form>`);$('#tender-form textarea').focus()}
function simulateBids(brief,due,projectId){const b=brief.toLocaleLowerCase('tr');const words=brief.split(/\s+/).filter(Boolean).length;const base=Math.min(40,Math.max(4,6+words/6));const pick=[];const add=id=>{if(!pick.includes(id))pick.push(id)};if(/video|kurgu|film|reels|motion/.test(b))add('HO');if(/tasarım|görsel|key visual|logo|afiş|banner|mizanpaj/.test(b)){add('SK');add('DO')}if(/metin|copy|yazı|slogan|içerik|post/.test(b)){add('R-COPY');add('SO')}if(/sosyal|instagram|linkedin|takvim/.test(b))add('R-SM');if(/strateji|sunum|teklif|konumland|marka/.test(b)){add('OE');add('UC')}if(/mekân|etkinlik|stand/.test(b))add('RV');if(/plan|termin|trafik/.test(b))add('R-TRAFFIC');if(pick.length<3){['OE','SK','R-COPY','DO'].forEach(add)}const bids=pick.slice(0,4).map(id=>state.twins.find(t=>t.id===id)).filter(t=>t&&!t.paused).map((t,i)=>{const f=t.kind==='Rol'?0.45:t.confidence==='HIGH'?0.9:t.confidence==='MED'?1.05:1.2;const likely=Math.max(2,Math.round(base*f*(1-i*0.12)));const free=t.capacity-twinPlanned(t);const risk=free<likely?'Yüksek':free<likely*1.5?'Orta':'Düşük';return {twin:t,low:Math.max(1,Math.round(likely*.75)),likely,high:Math.round(likely*1.4),free,risk}});const short=brief.length>48?brief.slice(0,46)+'…':brief;const plan=bids.map(x=>({name:`${x.twin.kind==='Rol'?x.twin.name:x.twin.role}: ${short}`,owner:x.twin.kind==='Kişi'?x.twin.id:'OE',hours:x.likely}));plan.push({name:`Kalite kontrol & teslim: ${short}`,owner:'OE',hours:2});return {id:'TN-'+(119+state.events.filter(e=>e.type==='tender.opened').length),brief,due,projectId,bids,plan,total:plan.reduce((s,p)=>s+p.hours,0),confidence:bids.every(b=>b.risk==='Düşük')?'HIGH':bids.some(b=>b.risk==='Yüksek')?'LOW':'MED'}}
function tenderResults(){const t=tender;openDialog(`${t.id} · teklifler`,`<div class="dialog-body"><p>${esc(t.brief)}</p><div class="actions">${badge(`Termin ${date(t.due)}`,'neutral')}${badge(project(t.projectId)?.name||'Proje','neutral')}${badge(`Plan güveni ${t.confidence}`)}</div><h3>İkiz teklifleri</h3><div class="table-wrap"><table class="bid-table"><thead><tr><th>İKİZ</th><th>SAAT (DÜŞÜK / OLASI / YÜKSEK)</th><th>BOŞ KAPASİTE</th><th>RİSK</th></tr></thead><tbody>${t.bids.map(b=>`<tr><td>${esc(b.twin.name)}<small>${esc(b.twin.role)} · ${b.twin.confidence}</small></td><td>${b.low} / <strong>${b.likely}</strong> / ${b.high}</td><td>${b.free} saat</td><td>${badge(b.risk)}</td></tr>`).join('')}</tbody></table></div><h3>Önerilen plan · ${t.total} saat</h3><ul class="plan-list">${t.plan.map(p=>`<li><span>${esc(p.name)}</span><span class="muted">${esc(person(p.owner))} · ${p.hours} s</span></li>`).join('')}</ul><div class="form-actions">${btn('Vazgeç','close','','close')}${btn('Planı onayla','approve-plan','primary','check')}</div></div>`)}

/* ---------- Otomasyon ---------- */
function automations(){const cap=state.settings.ai.dailyCap,spent=costToday(),pct=Math.min(100,Math.round(spent/cap*100));return head('ZEKÂ · OTOMASYON','Olaylar, ajanlar, maliyet.','core.events akışı ve ajan çalıştırmaları. Her çalıştırma model, token ve maliyetiyle kayıt altında.',btn('Olay yayınla','emit-event','','automation'))+`<section class="metrics" aria-label="Otomasyon özeti">${metric('Bugünkü olaylar',state.events.filter(e=>e.at.startsWith('14.10')).length,`${state.events.filter(e=>!e.processed).length} işlenmemiş`,'automation')}${metric('Ajan çalıştırmaları',state.runs.length,`${state.runs.filter(r=>r.status==='Hata').length} hata · ${state.runs.filter(r=>r.status==='Çalışıyor').length} sürüyor`,'cpu')}${metric('Günlük maliyet',usd(spent),`Tavan ${usd(cap)} · Ayarlar → Yapay Zekâ`,'finance')}<div class="metric"><div class="metric-top">Maliyet tavanı${ic('shield')}</div><div class="meter ${pct>80?'hot':''}" role="img" aria-label="Günlük tavanın yüzde ${pct}’i"><span style="width:${pct}%"></span></div><div class="metric-note">%${pct} kullanıldı · tavan aşılırsa ajanlar duraklar</div></div></section><section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>Ajan çalıştırmaları</h2>${badge(state.settings.ai.model,'neutral')}</div><div class="table-wrap"><table><thead><tr><th>AJAN</th><th>TETİKLEYİCİ</th><th>MODEL</th><th>TOKEN</th><th>MALİYET</th><th>DURUM</th><th>ZAMAN</th><th></th></tr></thead><tbody>${state.runs.map(r=>`<tr><td>${esc(r.agent)}</td><td class="mono">${esc(r.trigger)}</td><td class="mono">${esc(r.model)}</td><td>${r.tokens.toLocaleString('tr-TR')}</td><td>${usd(r.cost)}</td><td>${badge(r.status)}${r.error?`<small>${esc(r.error)}</small>`:''}</td><td>${esc(r.at)}</td><td>${r.status==='Hata'?`<button class="button sm" data-action="run-retry" data-id="${r.id}">Yeniden dene</button>`:`<button class="button sm" data-action="run-log" data-id="${r.id}">Günlük</button>`}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-header"><h2>Olay akışı · core.events</h2><span class="small muted">Her olay bir aggregate’e bağlıdır</span></div><div class="table-wrap"><table><thead><tr><th>TÜR</th><th>AGGREGATE</th><th>AKTÖR</th><th>ZAMAN</th><th>İŞLENDİ</th></tr></thead><tbody>${state.events.map(e=>`<tr><td class="mono">${esc(e.type)}</td><td class="mono">${esc(e.aggregate)}</td><td class="mono">${esc(e.actor)}</td><td>${esc(e.at)}</td><td>${e.processed?badge('Evet','success'):`<button class="button sm" data-action="event-process" data-id="${e.id}">İşle</button>`}</td></tr>`).join('')}</tbody></table></div></section>`}

/* ---------- Bağlantılar (JS Connect) ---------- */
function integrations(){const body=sub==='mcp'?connectMcp():sub==='api'?connectApi():connectIntegrations();const action=sub==='mcp'?btn('MCP sunucusu ekle','mcp-add','primary','plus'):sub==='api'?btn('Yeni token','token-new','primary','key'):btn('Tümünü senkronla','int-sync-all','','refresh');return head('SİSTEM · JS CONNECT','Dış dünyayla temiz bağlantı.','Entegrasyonlar, MCP sunucuları ve API erişimi tek yerde. Her bağlantı rıza ve kapsamla sınırlı.',action)+`<div class="toolbar">${subnav()}</div>${body}`}
function connectIntegrations(){return `<div class="int-grid">${state.integrations.map(i=>`<article class="panel int-card"><div class="top"><div class="name-cell"><div class="int-mark">${esc(i.name.slice(0,2))}</div><div><h3>${esc(i.name)}</h3><p>${esc(i.desc)}</p></div></div>${badge(i.status)}</div><div class="scopes">${i.scopes.map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><p>Son senkron: ${esc(i.lastSync)} · ${esc(i.freq)}</p><div class="actions">${i.status==='Bağlı değil'?btn('Bağlan','int-connect','primary','connect',`data-id="${i.id}"`):i.status==='Hata'?btn('Yeniden bağlan','int-connect','primary','refresh',`data-id="${i.id}"`)+btn('Test et','int-test','sm','play',`data-id="${i.id}"`):btn('Yapılandır','int-config','sm','settings',`data-id="${i.id}"`)+btn('Test et','int-test','sm','play',`data-id="${i.id}"`)+btn('Bağlantıyı kes','int-disconnect','sm danger','close',`data-id="${i.id}"`)}</div></article>`).join('')}</div>`}
function connectMcp(){return `<div class="banner">${ic('shield')}<span>Ajanlar ve ikizler yalnızca bir yöneticinin izin verdiği sunucuların araçlarını çağırabilir. İzin listesi rol bazlıdır; her çağrı Otomasyon’daki olay akışına yazılır.</span></div><div class="panel table-wrap" tabindex="0" role="region" aria-label="MCP sunucuları"><table><thead><tr><th>SUNUCU</th><th>URL</th><th>KİMLİK</th><th>ARAÇ</th><th>DURUM</th><th>İZİNLİ AJANLAR</th><th></th></tr></thead><tbody>${state.mcp.map(m=>`<tr><td>${esc(m.name)}</td><td class="mono">${esc(m.url)}</td><td>${badge(m.auth==='none'?'Yok':m.auth==='bearer'?'Bearer':'OAuth','neutral')}</td><td><button class="text-button" data-action="mcp-tools" data-id="${m.id}">${m.tools.length} araç</button></td><td>${badge(m.status)}</td><td>${m.roles.map(r=>`<span class="chip">${esc(r)}</span>`).join(' ')}</td><td><div class="actions"><button class="button sm" data-action="mcp-toggle" data-id="${m.id}">${m.status==='Aktif'?'Devre dışı bırak':'Etkinleştir'}</button><button class="button sm danger" data-action="mcp-remove" data-id="${m.id}">Sil</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">MCP sunucusu yok.</td></tr>'}</tbody></table></div>`}
function connectApi(){return `<section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>Kişisel erişim tokenları</h2><span class="small muted">Token yalnızca oluşturulurken bir kez gösterilir</span></div><div class="table-wrap"><table><thead><tr><th>AD</th><th>KAPSAM</th><th>OLUŞTURULDU</th><th>SON KULLANIM</th><th>DURUM</th><th></th></tr></thead><tbody>${state.tokens.map(t=>`<tr><td>${esc(t.name)}</td><td class="mono">${esc(t.scope)}</td><td>${esc(t.created)}</td><td>${esc(t.lastUsed)}</td><td>${badge(t.revoked?'İptal edildi':'Aktif')}</td><td>${t.revoked?'':`<button class="button sm danger" data-action="token-revoke" data-id="${t.id}">İptal et</button>`}</td></tr>`).join('')}</tbody></table></div></section><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Gelen webhook’lar</h2>${badge('HMAC-SHA256','neutral')}</div><div class="panel-body"><p class="small muted" style="margin-bottom:12px">Her istek <code class="mono">X-JS-Signature</code> başlığıyla imzalanır; sır ile HMAC-SHA256 doğrulanır. Sır yalnızca maskeli gösterilir.</p>${state.webhooksIn.map(w=>`<div class="session-row"><div><strong class="mono">${esc(w.path)}</strong><small>Sır: <span class="mono">${esc(w.secret.slice(0,6))}••••${esc(w.secret.slice(-4))}</span> · olaylar: ${esc(w.events)}</small></div><button class="button sm" data-action="hook-rotate" data-id="${w.id}">Sırrı döndür</button></div>`).join('')}</div></div><div class="panel"><div class="panel-header"><h2>Giden webhook’lar</h2>${btn('Ekle','hook-out-add','sm','plus')}</div><div class="panel-body">${state.webhooksOut.map(w=>`<div class="session-row"><div><strong class="mono">${esc(w.event)}</strong><small class="mono">${esc(w.url)}</small></div><div class="actions"><button class="button sm" data-action="hook-test" data-id="${w.id}">Test gönder</button>${sw(`webhooksOut.${state.webhooksOut.indexOf(w)}.active`,w.active,`${w.event} aktif`)}</div></div>`).join('')||'<p class="empty">Giden webhook yok.</p>'}</div></div></section>`}
function mcpAddDialog(){mcpDraftTools=null;openDialog('MCP sunucusu ekle',`<form class="dialog-body" id="mcp-form"><p>Sunucu eklendikten sonra yalnızca seçtiğin roller araçlarını çağırabilir. Keşif, sunucunun <code class="mono">tools/list</code> yanıtını simüle eder.</p><div class="form-grid"><label class="form-field">Ad<input name="name" required maxlength="40" placeholder="örn. slack-mcp"></label><label class="form-field">Kimlik doğrulama<select name="auth"><option value="none">Yok</option><option value="bearer" selected>Bearer token</option><option value="oauth">OAuth 2.1</option></select></label><label class="form-field full">URL<input name="url" type="url" required placeholder="https://mcp.jobsstudio.local/slack"></label><div class="form-field full">İzinli roller<div class="check-group">${['CEO','CFO','COO','CMO','CTO','CHRO','CCO','CLO','PM','Finans','Copy rol ikizi','Traffic rol ikizi'].map(r=>`<label><input type="checkbox" name="roles" value="${r}">${r}</label>`).join('')}</div></div></div><div class="form-actions" style="justify-content:start">${btn('Araçları keşfet','mcp-discover','','search')}</div><div id="mcp-tools"></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Sunucuyu ekle ${ic('plus')}</button></div></form>`);$('#mcp-form input').focus()}
function discoverTools(url){const u=url.toLocaleLowerCase('tr');const sets={slack:['post_message','list_channels','search_messages','add_reaction'],vimeo:['list_videos','get_review_link','upload_version'],google:['search_drive','create_doc','list_calendar','send_mail_draft','read_mail'],kolay:['list_employees','list_leaves','create_leave_request'],trello:['list_boards','create_card','move_card','add_comment'],parasut:['list_invoices','get_customer','cash_summary']};const k=Object.keys(sets).find(k=>u.includes(k));return sets[k]||['health','search','get_record','create_record']}
function tokenNewDialog(){openDialog('Yeni erişim tokenı',`<form class="dialog-body" id="token-form"><p>Token bir kez gösterilir; kapatınca tekrar görüntülenemez.</p><div class="form-grid"><label class="form-field full">Ad<input name="name" required maxlength="60" placeholder="Nerede kullanılacak?"></label><label class="form-field">Kapsam<select name="scope"><option>tasks:read</option><option>tasks:write</option><option>finance:read</option><option>events:read</option><option>files:read</option></select></label><label class="form-field">Geçerlilik<select name="expiry"><option>30 gün</option><option selected>90 gün</option><option>1 yıl</option></select></label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Token oluştur ${ic('key')}</button></div></form>`);$('#token-form input').focus()}
function hookOutDialog(){openDialog('Giden webhook ekle',`<form class="dialog-body" id="hook-form"><div class="form-grid"><label class="form-field">Olay türü<select name="event"><option>task.completed</option><option>task.created</option><option>approval.decided</option><option>decision.resolved</option><option>invoice.paid</option><option>twin.bid.created</option></select></label><label class="form-field">URL<input name="url" type="url" required placeholder="https://…"></label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Ekle ${ic('plus')}</button></div></form>`)}
function intConfigDialog(id){const i=state.integrations.find(x=>x.id===id);if(!i)return;const idx=state.integrations.indexOf(i);openDialog(`${esc(i.name)} · yapılandır`,`<div class="dialog-body"><p>${esc(i.desc)} · Kapsamlar OAuth onayında kullanıcıya gösterilir.</p><div class="form-grid"><label class="form-field">Senkron sıklığı${sel(`integrations.${idx}.freq`,['Gerçek zamanlı','15 dk','Saatlik','Günlük','Gece 03:00','İstek bazlı'],i.freq)}</label><label class="form-field">Hata durumunda<select><option>Yeniden dene (3×)</option><option>Duraklat ve bildir</option></select></label></div><h3>Kapsamlar</h3><div class="chip-row">${i.scopes.map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><div class="form-actions">${btn('Kapat','close','','close')}</div></div>`)}

/* ---------- Ayarlar ---------- */
function settings(){const parts={genel:settingsGeneral,bildirimler:settingsNotif,yapi:settingsStructure,ai:settingsAi,gorunum:settingsLook,veri:settingsData};return head('SİSTEM · AYARLAR','Sana göre bir ritim.','Çalışma alanının kuralları: zaman, bildirim, yapı, yapay zekâ ve veri.')+`<div class="settings-layout">${subnav()}<div>${(parts[sub]||settingsGeneral)()}</div></div>`}
function settingsGeneral(){const g=state.settings.general;return `<section class="panel settings-section"><h2>Genel</h2><p>Kuruluş bilgileri ve çalışma takvimi. Değişiklikler anında kaydedilir.</p><div class="form-grid"><label class="form-field">Kuruluş adı<input data-bind="settings.general.org" value="${esc(g.org)}" maxlength="60"></label><label class="form-field">Zaman dilimi${sel('settings.general.tz',['Europe/Istanbul','Europe/Berlin','Europe/London','UTC'],g.tz)}</label><label class="form-field">Para birimi${sel('settings.general.currency',['TRY','EUR','USD'],g.currency)}</label><label class="form-field">Hafta başlangıcı${sel('settings.general.weekStart',['Pazartesi','Pazar'],g.weekStart)}</label><label class="form-field">Dil${sel('settings.general.lang',['Türkçe','English'],g.lang)}</label><label class="form-field">Mesai başlangıcı<input type="time" data-bind="settings.general.workStart" value="${g.workStart}"></label><label class="form-field">Mesai bitişi<input type="time" data-bind="settings.general.workEnd" value="${g.workEnd}"></label><div class="form-field full">Hibrit ofis günleri<div class="check-group">${['Pzt','Sal','Çar','Per','Cum'].map(d=>`<label><input type="checkbox" data-bind-array="settings.general.hybrid" value="${d}" ${g.hybrid.includes(d)?'checked':''}>${d}</label>`).join('')}</div></div></div></section>`}
function settingsNotif(){const n=state.settings.notifications;const rows=[['task_assigned','Görev atandı'],['approval_pending','Onay bekliyor'],['board_decision','Kurul kararı'],['invoice_due','Fatura vadesi'],['integration_error','Entegrasyon hatası'],['twin_bid','İkiz teklifi'],['mention','Bahsetme / yorum']];const cols=[['app','Uygulama içi'],['email','E-posta'],['slack','Slack'],['push','Push']];return `<section class="panel settings-section"><h2>Bildirimler</h2><p>Olay türü × kanal matrisi. Kişisel üst yazımlar Profilim’de.</p><div class="table-wrap"><table class="matrix"><thead><tr><th>OLAY</th>${cols.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${rows.map(([k,l])=>`<tr><td>${l}</td>${cols.map(([c])=>`<td><input type="checkbox" data-bind="settings.notifications.matrix.${k}.${c}" ${n.matrix[k]?.[c]?'checked':''} aria-label="${l} · ${cols.find(x=>x[0]===c)[1]}"></td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="panel settings-section"><h2>Zamanlama</h2><p>Sessiz saatlerde yalnızca kritik entegrasyon hataları iletilir.</p><div class="form-grid"><label class="form-field">Sessiz saatler · başlangıç<input type="time" data-bind="settings.notifications.quietFrom" value="${n.quietFrom}"></label><label class="form-field">Sessiz saatler · bitiş<input type="time" data-bind="settings.notifications.quietTo" value="${n.quietTo}"></label><label class="form-field">Günlük özet saati<input type="time" data-bind="settings.notifications.digest" value="${n.digest}"></label></div><div class="toggle-row"><div>Haftalık kurul özeti<small>${n.weeklyBoardDay} ${n.weeklyBoardTime} · Slack #yonetim ve e-posta</small></div>${sw('settings.notifications.weeklyBoard',n.weeklyBoard,'Haftalık kurul özeti')}</div></section>`}
function settingsStructure(){const s=state.settings.structure;const roles=['Kurucu','PM','Kreatif','Finans','Müşteri'];return `<section class="panel settings-section"><h2>Modüller ve roller</h2><p>Hangi rol hangi modülü görür. Kapalı modül menüde görünmez; API’den de erişilemez.</p><div class="table-wrap"><table class="matrix module-table"><thead><tr><th>MODÜL</th>${roles.map(r=>`<th>${r}</th>`).join('')}</tr></thead><tbody>${Object.entries(s.modules).map(([m,rs])=>`<tr><td>${m}</td>${roles.map(r=>`<td><input type="checkbox" data-bind="settings.structure.modules.${m}.${r}" ${rs[r]?'checked':''} aria-label="${m} · ${r}"></td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="panel settings-section"><h2>Karar seviyeleri</h2><p>Harcama eşiği karar seviyesini belirler. Seviye 0 otomatik uygulanır, Seviye 1 PM onayı, Seviye 2 kurucu onayı ister.</p><div class="level-grid"><div class="level"><strong>Seviye 0 · Otomatik</strong>≤ ${money(s.level0Max)}<label class="form-field">Üst sınır (₺)<input type="number" min="0" step="500" data-bind="settings.structure.level0Max" data-number data-rerender value="${s.level0Max}"></label></div><div class="level"><strong>Seviye 1 · PM onayı</strong>${money(s.level0Max)} – ${money(s.level1Max)}<label class="form-field">Üst sınır (₺)<input type="number" min="0" step="1000" data-bind="settings.structure.level1Max" data-number data-rerender value="${s.level1Max}"></label></div><div class="level"><strong>Seviye 2 · Kurucu</strong>&gt; ${money(s.level1Max)}<p class="muted small" style="margin-top:10px">Kurul toplantısında gündeme alınır; cevap EVET / HAYIR / ERTELE.</p></div></div><h3 style="margin-top:8px">Onay zinciri</h3><div class="form-grid" style="margin-top:10px"><label class="form-field">1. adım${sel('settings.structure.chain.0',['PM','Brand Manager','Finans','Kurucu'],s.chain[0])}</label><label class="form-field">2. adım${sel('settings.structure.chain.1',['Kurucu','Finans','—'],s.chain[1])}</label></div></section><section class="panel settings-section"><h2>Görev türleri ve SLA</h2><p>İkizler tahmin verirken, COO ajanı SLA riski hesaplarken bu listeyi kullanır.</p><div class="table-wrap"><table class="sla-table"><thead><tr><th>GÖREV TÜRÜ</th><th>SLA (SAAT)</th><th></th></tr></thead><tbody>${s.taskTypes.map((t,i)=>`<tr><td><input data-bind="settings.structure.taskTypes.${i}.name" value="${esc(t.name)}" aria-label="Görev türü adı"></td><td><input type="number" min="1" data-bind="settings.structure.taskTypes.${i}.sla" data-number value="${t.sla}" aria-label="SLA saat"></td><td><button class="icon-button" data-action="sla-remove" data-id="${i}" aria-label="${esc(t.name)} türünü sil">${ic('trash')}</button></td></tr>`).join('')}</tbody></table></div><div class="form-actions" style="justify-content:start">${btn('Görev türü ekle','sla-add','','plus')}</div></section><section class="panel settings-section"><h2>Marka listesi</h2><p>${s.brands.length} marka · COO ajanının “17 marka” uyarısı bu listeden beslenir.</p>${chips('settings.structure.brands',s.brands,'Marka ekle ve Enter')}</section>`}
function settingsAi(){const a=state.settings.ai;const agents=state.board.agents;return `<section class="panel settings-section"><h2>Yapay zekâ</h2><p>Ajanlar ve ikizler için varsayılan model, maliyet tavanı ve etkin ajanlar. Gerçek API çağrısı yapılmaz.</p><div class="form-grid"><label class="form-field">Varsayılan model${sel('settings.ai.model',['claude-sonnet-5-5','claude-haiku-5-5','claude-opus-5-5'],a.model)}</label><label class="form-field">Günlük maliyet tavanı (USD)<div class="range-row"><input type="range" min="5" max="200" step="5" data-bind="settings.ai.dailyCap" data-number data-out="cap-out" value="${a.dailyCap}" aria-label="Günlük maliyet tavanı"><output id="cap-out">${usd(a.dailyCap)}</output></div></label></div><div class="toggle-row"><div>Bugünkü harcama<small>${usd(costToday())} · ${Math.round(costToday()/a.dailyCap*100)}% · tavan aşılırsa ajanlar duraklar, kurucuya bildirim gider</small></div>${btn('Modeli test et','ai-test','sm','play')}</div></section><section class="panel settings-section"><h2>Aktif ajanlar</h2><p>Kapalı ajan kurula katılmaz, öneri üretmez; mevcut kararları korunur.</p>${agents.map(g=>`<div class="toggle-row"><div>${g.role}<small>${esc(g.headline)}</small></div>${sw(`settings.ai.agents.${g.id}`,a.agents[g.id]!==false,`${g.role} ajanı`,'data-rerender')}</div>`).join('')}</section><section class="panel settings-section"><h2>Prompt sürümü</h2><p>Sistem promptları sürümlenir; değişiklik kurul kararı gerektirir.</p><div class="toggle-row"><div><strong>${a.promptVersion}</strong><small>Son güncelleme ${a.promptUpdated} · ${agents.length} ajan + 3 rol ikizi şablonu</small></div>${btn('Değişiklik günlüğü','prompt-log','sm','files')}</div></section>`}
function settingsLook(){return `<section class="panel settings-section"><h2>Görünüm</h2><p>Bu tarayıcıya özel tercihler.</p><div class="settings-row"><div><h3>Koyu görünüm</h3><p>Odaklanmak için ışığı azalt.</p></div><button class="switch" role="switch" aria-checked="${state.theme==='dark'}" aria-label="Koyu görünüm" data-action="theme"></button></div><div class="settings-row"><div><h3>Kompakt görünüm</h3><p>Listelerde daha fazla satır göster.</p></div><button class="switch" role="switch" aria-checked="${state.compact}" aria-label="Kompakt görünüm" data-action="compact"></button></div><div class="settings-row"><div><h3>Çalışma biçimi</h3><p>${storageAvailable?'Veriler yalnızca bu tarayıcıda tutulur.':'Tarayıcı depolaması kapalı; veriler yalnızca bu oturumda tutulur.'} Sunucu, kullanıcı hesabı ve gerçek AI bağlantısı yoktur.</p></div></div></section>`}
function settingsData(){const d=state.settings.data;return `<section class="panel settings-section"><h2>Veri</h2><p>Dışa aktarma, saklama süreleri ve yedek durumu.</p><div class="settings-row"><div><h3>Demo verisini dışa aktar</h3><p>Bu cihazdaki çalışma alanını JSON olarak indir.</p></div>${btn('JSON indir','export','','download')}</div><div class="settings-row"><div><h3>JSON içe aktar</h3><p>Daha önce dışa aktardığın dosyayı yükle.</p></div><label class="button" style="position:relative;overflow:hidden">${ic('upload')}<span>Dosya seç</span><input type="file" accept="application/json" id="import-file" style="position:absolute;width:1px;height:1px;opacity:0"></label></div><div class="settings-row"><div><h3>Başlangıca dön</h3><p>Bu prototipteki yerel değişiklikleri temizle.</p></div>${btn('Demoyu sıfırla','reset','danger','activity')}</div></section><section class="panel settings-section"><h2>Saklama süreleri</h2><p>Süre dolan kayıtlar gece işiyle arşive taşınır.</p><div class="form-grid"><label class="form-field">Olay akışı (gün)${sel('settings.data.retainEvents',[30,90,180,365],d.retainEvents,'data-number')}</label><label class="form-field">Ajan çalıştırmaları (gün)${sel('settings.data.retainRuns',[7,30,90],d.retainRuns,'data-number')}</label><label class="form-field">Dosya sürümleri (gün)${sel('settings.data.retainFiles',[90,365,730],d.retainFiles,'data-number')}</label></div></section><section class="panel settings-section"><h2>Son yedek</h2><p>MinIO → S3 soğuk yedek. CTO ajanı doğrulama süresini izler.</p><div class="toggle-row"><div><strong>${d.lastBackup}</strong> · ${d.backupSize}<small>Son doğrulama: ${d.backupVerified} ${d.verifyOk?badge('Doğrulandı'):badge('9 gündür doğrulanmadı','danger')}</small></div>${btn('Yedeği şimdi doğrula','backup-verify',d.verifyOk?'sm':'sm primary','shield')}</div></section>`}

/* ---------- Profilim ---------- */
function profileView(){const p=profile();const id=p.id;const P=`profiles.${id}`;const isMe=id==='BY';return head('SİSTEM · PROFİLİM',isMe?'Senin alanın.':`${esc(p.name)} olarak görüntülüyorsun.`,'Kapsam, yaklaşım, ikiz ayarları ve güvenlik. Değişiklikler anında kaydedilir ve işlem kaydına yazılır.',`<label class="form-field" style="min-width:220px">Görünümü değiştir (demo)<select data-bind="viewAs" data-rerender>${[['BY','Batuhan Berk Yaşar'],...state.team.map(t=>[t.id,t.name])].map(([v,n])=>`<option value="${v}" ${v===id?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`)+`<section class="panel profile-head"><div class="avatar">${initials(p.name)}</div><div><h1>${esc(p.name)}</h1><div class="muted">${esc(p.role)} · Jobs Studio Ankara</div><div class="actions" style="margin-top:10px">${badge(p.status)}${badge(`İkiz güveni ${p.twin.confidence}`,'ai')}</div></div><div class="form-grid"><label class="form-field">Durum${sel(`${P}.status`,['Müsait','Odakta','Toplantıda','İzinde'],p.status,'data-rerender')}</label><label class="form-field">Durum mesajı<input data-bind="${P}.statusMsg" value="${esc(p.statusMsg)}" maxlength="120" placeholder="Bugün ne var?"></label></div></section><div class="profile-grid"><section class="panel"><h2>Kapsamım</h2><p class="hint">İkiz yalnızca bu markalar ve görev türleri için teklif verir.</p><label class="form-field">Markalar</label>${chips(`${P}.brands`,p.brands,'Marka ekle')}<label class="form-field">Görev türleri</label>${chips(`${P}.taskTypes`,p.taskTypes,'Görev türü ekle')}<label class="form-field">Haftalık kapasite (saat)<div class="range-row"><input type="range" min="0" max="48" step="1" data-bind="${P}.capacity" data-number data-out="cap-${id}" value="${p.capacity}" aria-label="Haftalık kapasite"><output id="cap-${id}">${p.capacity} saat</output></div></label></section><section class="panel"><h2>Yaklaşımım</h2><p class="hint">İkiz, planı bu tercihlere göre kurar.</p><label class="form-field">Çalışma tercihleri<textarea data-bind="${P}.approach" maxlength="400" placeholder="Örn. Sabah kurgu, öğleden sonra toplantı">${esc(p.approach)}</textarea></label><label class="form-field">İletişim tercihi<textarea data-bind="${P}.comms" maxlength="300" placeholder="Örn. Kısa Slack mesajı; acilse ara">${esc(p.comms)}</textarea></label></section><section class="panel"><h2>Dijital ikizim</h2><p class="hint">İkiz profilin; rıza verdiğin veriden öğrenir.</p><table class="vel-table"><thead><tr><th>GÖREV TÜRÜ</th><th>ORT. SAAT</th></tr></thead><tbody>${p.twin.velocity.map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v}</td></tr>`).join('')||'<tr><td colspan="2" class="muted">Henüz veri yok.</td></tr>'}</tbody></table><div class="toggle-row"><div>Tahmin sapması<small>${esc(p.twin.bias)} · güven ${p.twin.confidence}</small></div></div><div class="toggle-row"><div>İkiz benim adıma teklif verebilir<small>İhalelerde saat ve risk tahmini verir</small></div>${sw(`${P}.twin.canBid`,p.twin.canBid,'İkiz teklif verebilir')}</div><div class="toggle-row"><div>Günlük plan taslağı göndersin<small>Her sabah ${state.settings.notifications.digest}</small></div>${sw(`${P}.twin.dailyDraft`,p.twin.dailyDraft,'Günlük plan taslağı')}</div><div class="toggle-row"><div>Ekran kategorisi paylaş (rıza)<small>ActivityWatch · yalnızca kategori, içerik değil</small></div>${sw(`${P}.twin.shareScreen`,p.twin.shareScreen,'Ekran kategorisi paylaş')}</div><label class="form-field">İkizim şunu konuşmasın</label>${chips(`${P}.twin.optout`,p.twin.optout,'Konu ekle')}<div class="toggle-row"><div>Profil onayı<small>${p.twin.approvedAt==='—'?'Henüz onaylanmadı; ikiz teklif veremez':`Son onay ${esc(p.twin.approvedAt)}`}</small></div>${btn('Profili onayla','profile-approve','sm primary','check')}</div></section><section class="panel"><h2>Entegrasyonlarım</h2><p class="hint">Kişisel hesap bağlantıları; kuruluş bağlantılarından ayrıdır.</p>${[['google','Google hesabı','Takvim ve Gmail okuma'],['trello','Trello üyeliği','Kart atamaları'],['slack','Slack','Doğrudan mesaj bildirimleri'],['kolayik','Kolay İK','İzin ve bordro görünümü']].map(([k,l,d])=>`<div class="toggle-row"><div>${l}<small>${d}</small></div><div class="actions">${badge(p.integrations[k]?'Bağlı':'Bağlı değil')}<button class="button sm" data-action="my-int" data-id="${k}">${p.integrations[k]?'Bağlantıyı kes':'Bağla'}</button></div></div>`).join('')}</section><section class="panel"><h2>Bildirimlerim</h2><p class="hint">Kuruluş matrisinin üstüne kişisel tercihler.</p>${[['mentions','Bahsetmeler','Anında push'],['digest','Günlük özet','Sabah e-postası'],['board','Kurul kararları','Cuma özeti ve bekleyen kararlar'],['quiet','Sessiz saatlere uy','20:00–08:00 arası bildirim yok']].map(([k,l,d])=>`<div class="toggle-row"><div>${l}<small>${d}</small></div>${sw(`${P}.notif.${k}`,p.notif[k],l)}</div>`).join('')}</section><section class="panel"><h2>Güvenlik</h2><p class="hint">Oturumlar ve giriş yöntemi.</p>${p.security.sessions.map(s=>`<div class="session-row"><div>${esc(s.device)} ${s.current?badge('Bu cihaz','success'):''}<small>${esc(s.place)} · ${esc(s.last)}</small></div>${s.current?'':`<button class="button sm" data-action="session-end" data-id="${s.id}">Oturumu kapat</button>`}</div>`).join('')}<div class="toggle-row"><div>İki adımlı doğrulama (MFA)<small>Doğrulayıcı uygulama</small></div>${sw(`${P}.security.mfa`,p.security.mfa,'MFA')}</div><div class="toggle-row"><div>Parolasız giriş<small>Passkey / cihaz anahtarı</small></div>${sw(`${P}.security.passwordless`,p.security.passwordless,'Parolasız giriş')}</div><div class="form-actions" style="justify-content:start">${btn('Şifreyi değiştir','password','sm','key')}</div></section></div>`}
Object.assign(views,{board,twins,automations,integrations,profile:profileView});

/* ---------- Routing ---------- */
const legacyRoutes={dashboard:'overview',clients:'crm',creative:'studio',team:'resources',files:'media',activity:'admin/security',settings:'admin/ayar-genel',automation:'automations',connect:'integrations'};
function navigate(ev){let h=location.hash.slice(1);if(legacyRoutes[h.split('/')[0]])h=legacyRoutes[h.split('/')[0]]+(h.includes('/')&&!legacyRoutes[h.split('/')[0]].includes('/')?'/'+h.split('/')[1]:'');const [next,s]=h.split('/');route=views[next]?next:'overview';sub=subTabs[route]?(subTabs[route].some(x=>x[0]===s)?s:subTabs[route][0][0]):'';filter='Tümü';query='';notifOpen=false;render();window.scrollTo(0,0);if(ev)$("#main")?.focus({preventScroll:true})}

/* ---------- Dialogs ---------- */
function openDialog(title,body,extra=''){lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Pencereyi kapat">${ic('close')}</button></div>${body}${extra}`;$('#modal').showModal()}
function closeDialog(){if($('#modal').open)$('#modal').close();if(lastFocus?.isConnected)lastFocus.focus();else $('#main')?.focus()}
function projectDetail(id){let p=project(id);if(!p)return;const ms=p.milestones||[];openDialog(esc(p.name),`<div class="dialog-body"><p>${esc(client(p.client))} / ${esc(p.type)} · Şablon: ${esc(p.template||'—')}</p><p>${esc(p.summary)}</p><div class="actions">${badge(p.status)}<span class="small muted">${date(p.due)} teslim${isClient()?'':` · ${money(p.budget)} plan`}</span></div><h3>Kilometre taşları</h3><ul class="meeting-list">${ms.map(([n,d,ok],i)=>`<li>${ok?ic('check'):ic('clock')}<span>${esc(n)} · ${date(d)} ${ok?badge('Tamamlandı'):`<button class="text-button" data-action="milestone-done" data-id="${p.id}" data-i="${i}">tamamla</button>`}</span></li>`).join('')||'<li>Kilometre taşı yok.</li>'}</ul><h3>Görevler · %${progress(p)} tamamlandı</h3>${myTasks().filter(t=>t.project===id).map(taskRow).join('')||'<p>Henüz görev eklenmedi.</p>'}${p.scopeChanges?.length?`<h3>Kapsam değişiklikleri</h3>${p.scopeChanges.map(s=>`<p>${esc(s.text)} · ${money(s.amount)} ${badge(s.status)}</p>`).join('')}`:''}<div class="form-actions">${btn('Briefi aç','brief','','files',`data-id="${id}"`)}${isClient()?'':btn('Kapsam değişikliği','scope-change','','flag',`data-id="${id}"`)+btn('Görev ekle','new-task','primary','plus',`data-id="${id}"`)}</div></div>`)}
function newProject(){openDialog('Yeni bir işe başlayalım.',`<form class="dialog-body" id="project-form"><p>Proje bu tarayıcıdaki demo çalışma alanına eklenir. Şablon, kilometre taşlarını önceden doldurur.</p><div class="form-grid"><label class="form-field full">Proje adı<input name="name" required maxlength="90" autocomplete="off" placeholder="İşe bir isim ver"></label><label class="form-field">Marka<select name="client">${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label class="form-field">Şablon<select name="template"><option>Sosyal aylık paket</option><option>Lansman filmi</option><option>Etkinlik</option><option>Web</option><option>Serbest</option></select></label><label class="form-field">Hizmet alanı<select name="type"><option>Marka deneyimi</option><option>Kampanya</option><option>Sosyal medya</option><option>Strateji</option><option>Video prodüksiyon</option><option>Dijital ürün</option><option>Etkinlik</option></select></label><label class="form-field">Teslim tarihi<input type="date" name="due" value="2026-11-13" required></label><label class="form-field">Planlanan bütçe (₺)<input type="number" name="budget" min="0" max="1000000000" step="1" value="0" required></label><label class="form-field full">Kısa kapsam<textarea name="summary" maxlength="600" placeholder="Hedef, çıktı ve beklenti"></textarea></label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Projeyi oluştur ${ic('arrow')}</button></div></form>`);$('#project-form input').focus()}
const templateMilestones={'Sosyal aylık paket':[['Aylık plan onayı',7],['Toplu müşteri onayı',14],['Yayın',30]],'Lansman filmi':[['Storyboard',5],['Çekim günü',12],['Offline kurgu v1',20],['Final teslim',30]],'Etkinlik':[['Mekân seçimi',7],['Tedarikçi onayı',14],['Run-of-show kilidi',25],['Etkinlik günü',30]],'Web':[['Sitemap & içerik',7],['Tasarım onayı',14],['Geliştirme',25],['Yayın',30]],'Serbest':[['Teslim',30]]};
function newTask(projectId,preset={}){openDialog('Bir sonraki adım.',`<form class="dialog-body" id="task-form"><div class="form-grid"><label class="form-field full">Görev<input name="name" required maxlength="120" placeholder="Somut bir çıktı yaz" value="${esc(preset.name||'')}"></label><label class="form-field">Proje<select name="project">${state.projects.map(p=>`<option value="${p.id}" ${p.id===projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="form-field">Sorumlu<select name="owner">${state.team.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</select></label><label class="form-field">Görev türü<select name="type">${state.settings.structure.taskTypes.map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></label><label class="form-field">Öncelik<select name="priority"><option>Normal</option><option>Yüksek</option><option>Acil</option></select></label><label class="form-field">Termin<input type="date" name="date" required value="2026-10-21"></label><label class="form-field">Etiketler (virgülle)<input name="labels" placeholder="sosyal, tasarım"></label></div><div class="form-actions"><button class="button primary" type="submit">Görevi ekle ${ic('plus')}</button></div></form>`);$('#task-form input').focus()}
function brief(id){let p=project(id);if(!p)return;openDialog(`${esc(p.name)} · Brief`,`<div class="dialog-body"><p>${esc(client(p.client))} / ${esc(p.type)} · Örnek içerik</p><h3>01 / Neyi değiştirmek istiyoruz?</h3><p>${esc(p.summary)||'Projenin iş hedefi keşif toplantısında netleştirilecek.'}</p><h3>02 / Kimin için?</h3><p>${p.type==='Etkinlik'?'Kurum çalışanları ve ekip liderleri.':'Markayla temas eden mevcut ve potansiyel müşteriler.'} Segment varsayımları araştırmayla doğrulanacak.</p><h3>03 / Beklenen çıktılar</h3><ul><li>Yaratıcı yön ve ana mesaj</li><li>Ana görsel ve kanal uyarlamaları</li><li>Uygulama planı ve teslim kontrol listesi</li></ul><h3>04 / Başarıyı nasıl okuyacağız?</h3><p>Teslimlerin zamanında onaylanması, kapsam değişikliklerinin kaydı ve hedef kitle geri bildirimi.</p><h3>05 / Sınırlar & teslim</h3><p>${date(p.due)} 2026${isClient()?'':` · Planlanan bütçe ${money(p.budget)}`}. Nihai kapsam, kullanım hakları ve yayın izni üretim öncesi karara bağlanır.</p><div class="form-actions">${btn('Briefi indir','download-brief','','download',`data-id="${p.id}"`)}</div></div>`)}
function proposal(){openDialog('Öneri → karar → kayıt',`<div class="dialog-body"><div class="banner">${ic('spark')}<span>COO ajanı önerisi. Gerçek AI modeli çalışmaz; öneri güncel veriden üretilmez.</span></div><h3>Teslim kontrolünü görünür kıl</h3><p>Wellana kampanyası için “Teslim öncesi kalite kontrolü” görevini Brand Manager’a ekle. Mevcut sorumluluklar ve ekip saatleri değişmez.</p><div class="panel" style="padding:18px"><p style="margin:0">Proje: <strong>Wellana · Sonbahar kampanyası</strong><br>Sorumlu: <strong>Öykü Erelmalı</strong><br>Termin: <strong>28 Ekim 2026</strong><br>Oluşacak kayıt: <strong>1 yeni görev</strong></p></div><p style="margin-top:18px">Bu senaryo kapasiteyi otomatik çözmez. Dışarıya mesaj veya dosya göndermez; uygulama kararını sen verirsin.</p><div class="form-actions">${state.proposalApplied?badge('Uygulandı'):btn('Öneriyi uygula','apply-proposal','primary','check')}</div></div>`)}
function command(){openDialog('Çalışma alanında ara',`<input class="command-input" id="command-input" type="search" aria-label="Sayfa veya proje ara" placeholder="Modül, bölüm, proje, marka veya bir komut…" autocomplete="off"><div id="command-results" class="command-list"></div>`,`<div class="dialog-note">↑ ↓ sonuçlar arasında gezin · Enter aç · Esc kapat · ⌘ / Ctrl K</div>`);commandResults('');$('#command-input').focus()}
function commandResults(q){let term=q.toLocaleLowerCase('tr'),items=[...visibleModules().map(m=>({label:m.name,kind:'Modül',id:m.id,action:'goto',icon:m.icon})),...Object.entries(subTabs).filter(([r])=>can(r)).flatMap(([r,ts])=>ts.map(([id,label])=>({label:`${moduleCatalog.find(n=>n.id===r)?.name} › ${label}`,kind:'Bölüm',id:`${r}/${id}`,action:'goto',icon:moduleCatalog.find(n=>n.id===r)?.icon}))),...myProjects().map(p=>({label:p.name,kind:'Proje',id:p.id,action:'project',icon:'projects'})),...(isClient()?[]:state.clients.map(c=>({label:c.name,kind:'Marka',id:c.id,action:'a360',icon:'crm'}))),...(can('board')?state.board.decisions.filter(d=>d.status==='Bekliyor').map(d=>({label:`${d.id} · ${d.title}`,kind:'Karar',id:'board',action:'goto',icon:'board'})):[]),...(isClient()?[{label:'Yeni talep aç',kind:'Komut',action:'portal-request',icon:'plus'}]:[{label:'Yeni proje oluştur',kind:'Komut',action:'new-project',icon:'plus'},{label:'Yeni görev',kind:'Komut',action:'new-task',icon:'tasks'},{label:'Yeni lead',kind:'Komut',action:'lead-new',icon:'crm'},{label:'Yeni iş ihalesi',kind:'Komut',action:'tender',icon:'twins'},{label:'Kurulu şimdi topla',kind:'Komut',action:'board-run',icon:'spark'},{label:'Rolü değiştir',kind:'Komut',action:'switch-role',icon:'user'}])].filter(x=>x.label.toLocaleLowerCase('tr').includes(term));$('#command-results').innerHTML=items.slice(0,40).map(x=>`<button class="command-result" data-action="${x.action}" data-id="${x.id||''}">${ic(x.icon)}${esc(x.label)}<small>${x.kind}</small></button>`).join('')||'<p class="empty">Eşleşme yok. Başka bir sözcük dene.</p>'}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(name,rows){const cell=x=>'"'+String(x??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';download(name,'﻿'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function briefText(p){return `JS ECOSYSTEM / JOBS STUDIO\nÖRNEK BRİEF — KURGUSAL PROJE\n\n${p.name}\nMüşteri: ${client(p.client)}\nHizmet: ${p.type}\nTeslim: ${p.due}\nPlan bütçe: ${money(p.budget)}\n\nHEDEF\n${p.summary}\n\nÇIKTILAR\nYaratıcı yön, ana mesaj, ana görsel ve uyarlamalar, teslim kontrol listesi.\n\nBu içerik gerçek müşteri briefi değildir.\n`}
function randomToken(){const a=new Uint8Array(24);crypto.getRandomValues(a);return 'jse_'+[...a].map(b=>b.toString(16).padStart(2,'0')).join('')}
function copyText(t){if(navigator.clipboard?.writeText)return navigator.clipboard.writeText(t).then(()=>toast('Panoya kopyalandı.'),()=>toast('Kopyalanamadı; metni elle seç.'));toast('Pano erişimi yok; metni elle seç.')}
function switchRoleDialog(){openDialog('Rolü değiştir (demo)',`<div class="dialog-body"><div class="banner">${ic('info')}<span>Demo giriş — kimlik doğrulama değildir. Rol; menü, veri kapsamı ve varsayılan ekranı değiştirir.</span></div><div class="login-roles compact">${accounts.map(a=>`<button class="role-card ${a.id===state.session.account?'current':''}" data-action="login" data-id="${a.id}"><span class="avatar">${initials(a.name)}</span><span class="rc-text"><strong>${esc(a.name)}</strong><small>${esc(a.title)}</small></span>${a.id===state.session.account?badge('Şu an','success'):badge(roleLabel[a.role],'neutral')}</button>`).join('')}</div><div class="form-actions">${btn('Çıkış yap (giriş ekranı)','logout','','logout')}${btn('Kapat','close','primary','check')}</div></div>`)}
function taskDetail(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;const p=project(t.project);const late=!t.done&&daysFromToday(t.due)<0;const slaLeft=t.sla-Math.round((t.logged||0)/60);openDialog(esc(t.name),`<div class="dialog-body"><div class="actions">${badge(t.stage||'Brief')}${badge(t.priority)}${late?badge('Gecikmiş'):badge(`${Math.max(0,daysFromToday(t.due))} gün kaldı`,'neutral')}${badge(`SLA ${t.sla||'—'} s · kalan ${slaLeft} s`,slaLeft<8?'danger':'neutral')}${t.client_visible?badge('Müşteriye açık','success'):badge('Dahili')}</div><p style="margin-top:12px">${esc(p?.name||'')} · ${esc(client(p?.client))} · Sorumlu ${esc(person(t.owner))} · ${esc(t.type||'')}</p>${t.source?`<p class="small muted">Kaynak: ${esc(t.source)} ${t.sourceMail?`· <a href="#inbox" data-action="goto" data-id="inbox">e-postayı aç</a>`:''}</p>`:''}<div class="chip-row" style="margin:10px 0">${(t.labels||[]).map(l=>`<span class="chip">${esc(l)}</span>`).join('')}</div>${isClient()?'':`<div class="form-grid"><label class="form-field">Aşama<select data-bind="tasks.${state.tasks.indexOf(t)}.stage" data-rerender>${['Brief','Kapsam','Plan','Üretim','İç revize','Onay','Teslim','Arşiv'].map(s=>option(s,s,t.stage)).join('')}</select></label><label class="form-field">Sorumlu<select data-bind="tasks.${state.tasks.indexOf(t)}.owner">${state.team.map(m=>option(m.id,m.name,t.owner)).join('')}</select></label><label class="form-field">Kayıtlı süre<input type="number" min="0" step="15" data-bind="tasks.${state.tasks.indexOf(t)}.logged" data-number value="${t.logged||0}" aria-label="Kayıtlı dakika"> <span class="small muted">dk</span></label><label class="form-field">Müşteriye görünür${sw(`tasks.${state.tasks.indexOf(t)}.client_visible`,t.client_visible,'Müşteriye görünür')}</label></div>`}<h3>Yorumlar</h3>${(t.comments||[]).map(c=>`<div class="comment"><small>${esc(person(c.who))} · ${esc(c.at)}${c.client?' · müşteri':''}</small><p>${esc(c.text)}</p></div>`).join('')||'<p class="muted small">Henüz yorum yok.</p>'}<form id="comment-form" data-id="${t.id}" class="form-grid" style="margin-top:10px"><label class="form-field full">Yorum<textarea name="text" maxlength="500" placeholder="Not, revizyon ya da soru"></textarea></label><div class="form-actions" style="grid-column:1/-1">${isClient()?'':btn('Süre başlat','timer-start','','timer',`data-id="${t.id}"`)}${btn(t.done?'Yeniden aç':'Tamamla','task','','check',`data-id="${t.id}"`)}<button class="button primary" type="submit">Yorum ekle ${ic('plus')}</button></div></form></div>`)}
function scopeChangeDialog(id){const p=project(id);if(!p)return;openDialog('Kapsam değişikliği talebi',`<form class="dialog-body" id="scope-form" data-id="${id}"><p>${esc(p.name)} için kapsam dışı iş. Onay Merkezi’ne “Kapsam dışı” kaydı düşer; eşik seviyesi tutara göre belirlenir.</p><div class="form-grid"><label class="form-field full">Açıklama<input name="text" required maxlength="160" placeholder="Örn. +1 Reels ve ek lokasyon çekimi"></label><label class="form-field">Ek tutar (₺)<input type="number" name="amount" min="0" value="12000"></label><label class="form-field">Ek süre (gün)<input type="number" name="days" min="0" value="3"></label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Onaya gönder ${ic('approvals')}</button></div></form>`)}

/* ---------- Actions ---------- */
function addNotification(text,routeTo){state.notifications.unshift({id:'n'+Date.now(),text,time:now().slice(-5),route:routeTo,read:false});state.notifications=state.notifications.slice(0,20)}
function done(msg,logText,rerender=true){if(logText)log(logText);else save();if(rerender)render();if(msg)toast(msg)}
function approvalLevel(amount){const s=state.settings.structure;return amount<=s.level0Max?'Seviye 0 · otomatik':amount<=s.level1Max?'Seviye 1 · PM onayı':'Seviye 2 · kurucu onayı'}
function requestApproval(o){const a={id:uid('a'),status:'Bekliyor',feedback:'',amount:0,requested:now(),by:account().person,deadline:'2026-10-21',delegate:'',version:'—',project:'',...o};state.approvals.unshift(a);emit('approval.requested',`approval:${a.id}`);addNotification(`Onay bekliyor: ${a.name}`,'approvals');return a}
const coreActions={
menu(b){const open=$('.sidebar').classList.toggle('open');b.setAttribute('aria-expanded',open);if(open)$('.sidebar a').focus()},
close(){closeDialog()},
theme(){state.theme=state.theme==='dark'?'light':'dark';done(null,null)},
compact(){state.compact=!state.compact;done(null,null)},
command(){command()},
goto(b){closeDialog();location.hash=b.dataset.id;if(location.hash.slice(1)===b.dataset.id)navigate()},
sub(b){location.hash=`${route}/${b.dataset.id}`},
filter(b){filter=b.dataset.filter;render()},
notif(){notifOpen=!notifOpen;render();if(notifOpen)$('.notif-item')?.focus()},
'notif-read-all'(){state.notifications.forEach(n=>n.read=true);notifOpen=false;done('Tüm bildirimler okundu sayıldı.',null)},
'notif-open'(b){const n=state.notifications.find(x=>x.id===b.dataset.id);if(!n)return;n.read=true;notifOpen=false;save();location.hash=n.route;render()},
login(b){const a=accounts.find(x=>x.id===b.dataset.id);if(!a)return;const first=!state.session.loggedIn;state.session.loggedIn=true;state.session.account=a.id;state.viewAs=a.person==='CL'?'BY':a.person;if($('#modal').open)closeDialog();log(`Demo giriş: ${a.name} (${roleLabel[a.role]}) — kimlik doğrulama değildir`);const target=a.role==='client'?'portal':a.role==='creative'?'mywork':a.role==='finance'?'finance':a.role==='hr'?'people':a.role==='payroll'?'people/bordro':'overview';location.hash=target;navigate();toast(`${a.name} olarak görüntülüyorsun · ${roleLabel[a.role]}${first?'':' (rol değişti)'}`)},
logout(){state.session.loggedIn=false;closeDialog();log('Demo oturumu kapatıldı.');render();window.scrollTo(0,0)},
'switch-role'(){if($('#modal').open)closeDialog();switchRoleDialog()},
'new-project'(){if($('#modal').open)closeDialog();newProject()},
'new-task'(b){if($('#modal').open)closeDialog();newTask(b.dataset.id)},
project(b){if($('#modal').open)closeDialog();projectDetail(b.dataset.id)},
'task-open'(b){if($('#modal').open)closeDialog();taskDetail(b.dataset.id)},
task(b){let t=state.tasks.find(t=>t.id===b.dataset.id);if(!t)return;t.done=!t.done;if(t.done)t.stage='Teslim';else if(t.stage==='Teslim'||t.stage==='Arşiv')t.stage='Üretim';log(`${t.done?'Görev tamamlandı':'Görev yeniden açıldı'}: ${t.name}`);emit(t.done?'task.completed':'task.reopened',`task:${t.id}`);const inside=!!b.closest('dialog');render();if(inside){closeDialog()}toast(t.done?'Görev tamamlandı.':'Görev yeniden açıldı.')},
'milestone-done'(b){const p=project(b.dataset.id);if(!p)return;p.milestones[Number(b.dataset.i)][2]=true;closeDialog();done('Kilometre taşı tamamlandı.',`Kilometre taşı tamamlandı: ${p.name} · ${p.milestones[Number(b.dataset.i)][0]}`);projectDetail(p.id)},
'scope-change'(b){if($('#modal').open)closeDialog();scopeChangeDialog(b.dataset.id)},
brief(b){if($('#modal').open)closeDialog();brief(b.dataset.id)},
proposal(){proposal()},
'apply-proposal'(){if(state.proposalApplied)return;state.tasks.unshift({id:'t-proposal',name:'Teslim öncesi kalite kontrolü',project:'p1',owner:'OE',done:false,date:'28 Eki',due:'2026-10-28',priority:'Normal',stage:'Plan',labels:['kalite'],type:'Müşteri status raporu',sla:24,logged:0,comments:[],client_visible:false,source:'COO ajanı önerisi'});state.proposalApplied=true;emit('task.created','task:t-proposal','agent:coo');closeDialog();done('Onaylandı. Bir görev eklendi; işlem kaydedildi.','İnsan onayıyla COO önerisi uygulandı: 1 kalite kontrol görevi oluşturuldu.')},
'download-brief'(b){download(`${b.dataset.id}-ornek-brief.txt`,briefText(project(b.dataset.id)));toast('Örnek brief indiriliyor.')},
export(){download('js-ecosystem-demo.json',JSON.stringify(state,null,2),'application/json');toast('Demo verisi dışa aktarıldı.')},
reset(){openDialog('Demo sıfırlansın mı?',`<div class="dialog-body"><p>Eklediğin projeler, kararlar, ayarlar ve yerel kayıtlar başlangıç verileriyle değiştirilecek. Önce Admin → Ayarlar → Veri’den JSON yedeği indirebilirsin.</p><div class="form-actions">${btn('Vazgeç','close','','close')}${btn('Sıfırla','confirm-reset','danger','activity')}</div></div>`)},
'confirm-reset'(){const s=state.session;state=seed();state.session=s;save();closeDialog();filter='Tümü';render();toast('Demo başlangıç durumuna döndü.')},
copy(b){copyText(b.dataset.id)},
'chip-remove'(b){const arr=getPath(state,b.dataset.path);if(!Array.isArray(arr))return;setPath(state,b.dataset.path,arr.filter(x=>x!==b.dataset.id));done('Kaldırıldı.',`Liste güncellendi (${b.dataset.path.split('.').at(-1)}): ${b.dataset.id} kaldırıldı`)},
toggle(b){const v=b.getAttribute('aria-checked')!=='true';setPath(state,b.dataset.path,v);b.setAttribute('aria-checked',v);log(`${b.getAttribute('aria-label')}: ${v?'açık':'kapalı'}`);toast(`${b.getAttribute('aria-label')} ${v?'açıldı':'kapatıldı'}.`);if(b.dataset.rerender!==undefined)render()},
'timer-start'(b){state.timer={task:b.dataset.id,startedAt:Date.now()};closeDialog();log(`Süre başlatıldı: ${state.tasks.find(t=>t.id===b.dataset.id)?.name}`);location.hash='mywork/zaman';navigate();toast('Zamanlayıcı başladı.')},
'timer-stop'(){const tm=state.timer;if(!tm)return;const t=state.tasks.find(x=>x.id===tm.task);const mins=Math.max(1,Math.round((Date.now()-tm.startedAt)/60000));if(t)t.logged=(t.logged||0)+mins;state.timer=null;emit('time.logged',`task:${tm.task}`);done(`${mins} dk kaydedildi.`,`Zaman kaydı: ${t?.name} +${mins} dk`)}
};
Object.assign(actions,coreActions);
Object.assign(forms,{
'project-form'(get){if(!get('name'))return;const tpl=get('template');const ms=(templateMilestones[tpl]||[]).map(([n,d])=>{const dt=new Date(TODAY+'T12:00:00');dt.setDate(dt.getDate()+d);return [n,dt.toISOString().slice(0,10),false]});state.projects.unshift({id:'p'+Date.now(),name:get('name'),client:get('client'),type:get('type'),template:tpl,status:'Planlama',due:get('due'),budget:Number(get('budget')),summary:get('summary'),milestones:ms,scopeChanges:[],client_visible:true});emit('project.created','project:new');log(`Proje oluşturuldu: ${get('name')} (${tpl})`);closeDialog();location.hash='projects';filter='Tümü';render();toast('Yeni proje çalışma alanına eklendi.')},
'task-form'(get){if(!get('name'))return;state.tasks.unshift({id:'t'+Date.now(),name:get('name'),project:get('project'),owner:get('owner'),priority:get('priority'),done:false,date:date(get('date')),due:get('date'),stage:'Brief',labels:get('labels').split(',').map(x=>x.trim()).filter(Boolean),type:get('type'),sla:state.settings.structure.taskTypes.find(t=>t.name===get('type'))?.sla||48,logged:0,comments:[],client_visible:false});emit('task.created','task:new');log(`Görev oluşturuldu: ${get('name')}`);closeDialog();render();toast('Görev eklendi.')},
'comment-form'(get,data,f){if(!get('text'))return;const t=state.tasks.find(x=>x.id===f.dataset.id);if(!t)return;t.comments=t.comments||[];t.comments.push({who:account().person,text:get('text'),at:now(),client:isClient()});log(`Yorum eklendi: ${t.name}`);closeDialog();render();taskDetail(t.id);toast('Yorum eklendi.')},
'scope-form'(get,data,f){const p=project(f.dataset.id);if(!p||!get('text'))return;const amount=Number(get('amount'));p.scopeChanges=p.scopeChanges||[];const sc={text:get('text'),amount,days:Number(get('days')),status:'Bekliyor'};p.scopeChanges.push(sc);requestApproval({name:`${p.name} · kapsam değişikliği`,project:p.id,kind:'Kapsam dışı',amount,desc:`${get('text')} · +${get('days')} gün · ${approvalLevel(amount)}`});log(`Kapsam değişikliği onaya gönderildi: ${p.name} · ${money(amount)}`);closeDialog();render();toast(`Onay Merkezi’ne gönderildi (${approvalLevel(amount)}).`)}
});

/* ---------- Global listeners ---------- */
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const b=e.target.closest('[data-action]');if(!b){if(notifOpen&&!e.target.closest('.notif-wrap')){notifOpen=false;render()}return}if(notifOpen&&!b.closest('.notif-wrap'))notifOpen=false;if(b.closest('form')&&!b.hasAttribute('type'))e.preventDefault();if(b.tagName==='A')e.preventDefault();const fn=actions[b.dataset.action];if(fn)fn(b)});
document.addEventListener('click',e=>{if(e.target.closest('.sidebar a')){$('.sidebar').classList.remove('open');$('.mobile-menu')?.setAttribute('aria-expanded','false')}if($('.sidebar')?.classList.contains('open')&&!e.target.closest('.sidebar')&&!e.target.closest('[data-action="menu"]')){$('.sidebar').classList.remove('open');$('.mobile-menu')?.setAttribute('aria-expanded','false')}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='command-input')commandResults(t.value);if(t.dataset.search!==undefined){query=t.value;const target=document.getElementById(t.dataset.search);if(target&&typeof window[t.dataset.fn]==='function')target.innerHTML=window[t.dataset.fn]();}if(t.dataset.person){const id=t.dataset.person,h=Number(t.value);$(`#capacity-${id}`).innerHTML=`${h} <span>/ 40 saat</span>`;$(`#free-${id}`).textContent=h>40?`${h-40} saat fazla planlandı`:`${40-h} saat müsait`;$(`#load-${id}`).textContent=`%${Math.round(h/40*100)}`;t.setAttribute('aria-valuetext',`${h} saat`)}if(t.dataset.out){const o=document.getElementById(t.dataset.out);if(o)o.textContent=t.dataset.bind==='settings.ai.dailyCap'?usd(Number(t.value)):`${t.value} saat`}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.person){let p=state.team.find(x=>x.id===t.dataset.person);p.hours=Number(t.value);log(`Kapasite planı güncellendi: ${p.name}, ${p.hours} saat.`);toast('Haftalık plan kaydedildi.');return}if(t.id==='import-file'){const f=t.files?.[0];if(!f)return;f.text().then(txt=>{const parsed=JSON.parse(txt);if(parsed?.version!==VERSION||!Array.isArray(parsed.projects))throw new Error('format');state=parsed;save();render();toast('Veri içe aktarıldı.');log('JSON içe aktarıldı.')}).catch(()=>toast('Dosya okunamadı: geçerli bir JS Ecosystem v4 yedeği değil.'));return}if(t.dataset.bindArray){const arr=getPath(state,t.dataset.bindArray)||[];const next=t.checked?[...new Set([...arr,t.value])]:arr.filter(x=>x!==t.value);setPath(state,t.dataset.bindArray,next);log(`Ayar güncellendi: ${t.dataset.bindArray.split('.').at(-1)} = ${next.join(', ')||'—'}`);toast('Kaydedildi.');return}if(t.dataset.bind){const path=t.dataset.bind;let v=t.type==='checkbox'?t.checked:t.value;if(t.dataset.number!==undefined)v=Number(v);setPath(state,path,v);const label=t.closest('label')?.firstChild?.textContent?.trim()||t.getAttribute('aria-label')||path.split('.').at(-1);log(`${label} güncellendi: ${typeof v==='boolean'?(v?'açık':'kapalı'):v}`);toast('Kaydedildi.');if(t.dataset.rerender!==undefined)render()}if(t.dataset.uiSel!==undefined){ui[t.dataset.uiSel]=t.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=new FormData(f),get=n=>String(data.get(n)||'').trim();const fn=forms[f.id];if(fn)fn(get,data,f,e)});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!state.session.loggedIn)return;if($('#modal').open)closeDialog();else command()}if(e.key==='Escape'){if($('.sidebar')?.classList.contains('open')){$('.sidebar').classList.remove('open');$('.mobile-menu').focus();$('.mobile-menu').setAttribute('aria-expanded','false')}if(notifOpen){notifOpen=false;render();$('.bell')?.focus()}}if(e.key==='Enter'&&e.target.dataset?.chipAdd){e.preventDefault();const v=e.target.value.trim();if(!v)return;const arr=getPath(state,e.target.dataset.chipAdd)||[];if(!arr.includes(v)){setPath(state,e.target.dataset.chipAdd,[...arr,v]);log(`Liste güncellendi (${e.target.dataset.chipAdd.split('.').at(-1)}): ${v} eklendi`);render();toast('Eklendi.');[...document.querySelectorAll('[data-chip-add]')].find(x=>x.dataset.chipAdd===e.target.dataset.chipAdd)?.focus()}}if($('#command-input')&&$('#modal').open&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const results=[...document.querySelectorAll('.command-result')];let i=results.indexOf(document.activeElement);i=e.key==='ArrowDown'?(i+1)%results.length:(i-1+results.length)%results.length;results[i]?.focus()}if(e.key==='Enter'&&e.target.id==='command-input'){e.preventDefault();$('.command-result')?.click()}});
function boot(){loadState();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});$('#modal').addEventListener('close',()=>{if(lastFocus?.isConnected&&!document.activeElement?.closest('.main'))lastFocus.focus({preventScroll:true})});window.addEventListener('hashchange',navigate);navigate();setInterval(()=>{const el=$('#timer-live');if(el&&state.timer){const s=Math.round((Date.now()-state.timer.startedAt)/1000);el.textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}},1000)}
document.addEventListener('DOMContentLoaded',boot);
/* ---------- Legacy actions: board, twins, automation, connect, settings, profile ---------- */
Object.assign(actions,{
// board
decide(b){const d=state.board.decisions.find(x=>x.id===b.dataset.id);if(!d)return;const v=b.dataset.value;d.status=v;d.decidedAt=v==='Bekliyor'?'':now();emit('decision.resolved',`decision:${d.id}`,'user:BY');if(v==='EVET'&&d.id==='CCO-2026W42-03'&&!state.tasks.some(t=>t.id==='t-clayton')){state.tasks.unshift({id:'t-clayton',name:'Clayton lansman teklifi tasarımı',project:'p2',owner:'DO',done:false,date:'23 Eki',due:'2026-10-23',priority:'Yüksek',stage:'Brief',labels:['tasarım','teklif'],type:'Teklif / sunum',sla:96,logged:0,comments:[],client_visible:false,source:'Kurul kararı CCO-2026W42-03'})}if(v==='EVET'&&d.id==='CTO-2026W42-01'){state.settings.data.verifyOk=true;state.settings.data.backupVerified=now();const cto=state.board.agents.find(a=>a.id==='cto');cto.health='GREEN';cto.headline='Yedek doğrulandı; gece 03:00 planı aktif.'}if(v==='EVET'&&d.id==='COO-2026W42-01'){const coo=state.board.agents.find(a=>a.id==='coo');coo.health='AMBER';coo.headline='Copy rol ikizi devrede; SLA riski izleniyor.'}state.board.kpi.toFounder=Math.max(0,pendingDecisions());done(v==='Bekliyor'?'Karar geri alındı.':`Karar kaydedildi: ${v}.`,v==='Bekliyor'?`Karar geri alındı: ${d.id}`:`Kurul kararı · ${d.id}: ${v} — ${d.action}`)},
agent(b){agentDetail(b.dataset.id)},
'agent-toggle'(b){const id=b.dataset.id;const on=state.settings.ai.agents[id]!==false;state.settings.ai.agents[id]=!on;closeDialog();done(on?'Ajan duraklatıldı.':'Ajan etkinleştirildi.',`Ajan ${on?'duraklatıldı':'etkinleştirildi'}: ${id.toUpperCase()}`)},
'board-run'(){if($('#modal').open)closeDialog();const auto=['Trello etiket şeması doğrulandı (COO).','Vadesi yaklaşan 2 fatura için hatırlatma gönderildi (CFO).','Ekip kapasite özeti #ops kanalına paylaşıldı (CHRO).'];state.board.lastMeeting={date:`${new Date().toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric'})} · şimdi`,auto:3,founder:pendingDecisions(),notes:[...auto.map(a=>'Seviye 0: '+a),...state.board.decisions.filter(d=>d.status==='Bekliyor').map(d=>`Kurucuya: ${d.title} (${d.id})`)]};state.runs.unshift({id:'r'+Date.now(),agent:'Başkan',trigger:'manual:board-run',model:state.settings.ai.model,tokens:61200,cost:0.84,status:'Başarılı',at:now()});emit('board.meeting.completed','board:'+now(),'agent:chair');addNotification(`Kurul toplandı: 3 otomatik karar, ${pendingDecisions()} karar kurucuda.`,'board');done('Kurul toplandı: 3 Seviye 0 karar uygulandı.',`Kurul toplantısı çalıştırıldı: 3 otomatik karar, ${pendingDecisions()} kurucuya.`)},
// twins
twin(b){twinDetail(b.dataset.id)},
'twin-toggle'(b){const t=state.twins.find(x=>x.id===b.dataset.id);if(!t)return;t.paused=!t.paused;closeDialog();done(t.paused?'İkiz duraklatıldı.':'İkiz etkin.',`İkiz ${t.paused?'duraklatıldı':'etkinleştirildi'}: ${t.name}`)},
tender(){if($('#modal').open)closeDialog();tenderDialog()},
'approve-plan'(){if(!tender)return;const t=tender;const d=date(t.due);t.plan.forEach((p,i)=>state.tasks.unshift({id:`t${Date.now()}${i}`,name:p.name,project:t.projectId,owner:p.owner,done:false,date:d,due:t.due,priority:'Normal',stage:'Plan',labels:['ihale'],type:'Teklif / sunum',sla:96,logged:0,comments:[],client_visible:false,source:`İhale ${t.id}`}));emit('tender.plan.approved',`tender:${t.id}`);t.bids.forEach(b=>emit('twin.bid.accepted',`tender:${t.id}`,`twin:${b.twin.id}`));state.runs.unshift({id:'r'+Date.now(),agent:'Twins',trigger:`tender:${t.id}`,model:state.settings.ai.model,tokens:18000+t.bids.length*4200,cost:+(0.2+t.bids.length*0.06).toFixed(2),status:'Başarılı',at:now()});closeDialog();tender=null;location.hash='tasks';done(`Plan onaylandı: ${t.plan.length} görev oluşturuldu.`,`İhale ${t.id} planı onaylandı: ${t.plan.length} görev, ${t.total} saat.`)},
// automation
'emit-event'(){emit('demo.ping','system:prototype','user:BY',false);done('Olay yayınlandı (işlenmemiş).','Demo olayı yayınlandı: demo.ping')},
'event-process'(b){const e=state.events.find(x=>x.id===b.dataset.id);if(!e)return;e.processed=true;done('Olay işlendi.',`Olay işlendi: ${e.type} (${e.aggregate})`)},
'run-retry'(b){const r=state.runs.find(x=>x.id===b.dataset.id);if(!r)return;r.status='Başarılı';r.error='';r.at=now();r.cost=+(r.cost+0.02).toFixed(2);const k=state.integrations.find(i=>i.id==='kolayik');if(k&&r.trigger.includes('kolayik')){k.status='Bağlı';k.lastSync=now()}done('Çalıştırma yeniden denendi: başarılı.',`Ajan çalıştırması yeniden denendi: ${r.agent} · ${r.trigger}`)},
'run-log'(b){const r=state.runs.find(x=>x.id===b.dataset.id);if(!r)return;openDialog(`${r.agent} · ${r.trigger}`,`<div class="dialog-body"><div class="actions">${badge(r.status)}${badge(r.model,'neutral')}${badge(`${r.tokens.toLocaleString('tr-TR')} token · ${usd(r.cost)}`,'neutral')}</div><div class="token-box">[${r.at}] run ${r.id} started\n[${r.at}] tools: ${state.mcp.filter(m=>m.status==='Aktif').map(m=>m.name).join(', ')||'—'}\n[${r.at}] prompt ${state.settings.ai.promptVersion}\n[${r.at}] ${r.error||'completed · outputs written to core.events'}</div><div class="form-actions">${btn('Kapat','close','','close')}</div></div>`)},
// connect
'int-connect'(b){const i=state.integrations.find(x=>x.id===b.dataset.id);if(!i)return;i.status='Bağlı';i.lastSync=now();emit('integration.connected',`integration:${i.id}`);done(`${i.name} bağlandı (OAuth simülasyonu).`,`Entegrasyon bağlandı: ${i.name}`)},
'int-disconnect'(b){const i=state.integrations.find(x=>x.id===b.dataset.id);if(!i)return;i.status='Bağlı değil';i.lastSync='—';emit('integration.disconnected',`integration:${i.id}`);done(`${i.name} bağlantısı kesildi.`,`Entegrasyon bağlantısı kesildi: ${i.name}`)},
'int-test'(b){const i=state.integrations.find(x=>x.id===b.dataset.id);if(!i)return;const ok=i.status==='Bağlı';done(ok?`${i.name} testi başarılı · ${120+Math.floor(Math.random()*300)} ms`:`${i.name} testi başarısız: token süresi dolmuş.`,`Entegrasyon testi: ${i.name} → ${ok?'başarılı':'hata'}`,false)},
'int-config'(b){intConfigDialog(b.dataset.id)},
'int-sync-all'(){state.integrations.filter(i=>i.status==='Bağlı').forEach(i=>i.lastSync=now());done('Bağlı entegrasyonlar senkronlandı.','Tüm entegrasyonlar senkronlandı.')},
'mcp-add'(){if($('#modal').open)closeDialog();mcpAddDialog()},
'mcp-discover'(){const url=$('#mcp-form [name=url]')?.value||'';if(!url){$('#mcp-form [name=url]').focus();toast('Önce URL gir.');return}mcpDraftTools=discoverTools(url);$('#mcp-tools').innerHTML=`<p class="small muted" style="margin:12px 0 0">${mcpDraftTools.length} araç bulundu:</p><ul class="tool-list">${mcpDraftTools.map(t=>`<li>${ic('cpu')}<code>${esc(t)}</code></li>`).join('')}</ul>`;toast(`${mcpDraftTools.length} araç keşfedildi.`)},
'mcp-tools'(b){const m=state.mcp.find(x=>x.id===b.dataset.id);if(!m)return;openDialog(`${esc(m.name)} · araçlar`,`<div class="dialog-body"><p class="mono">${esc(m.url)}</p><ul class="tool-list">${m.tools.map(t=>`<li>${ic('cpu')}<code>${esc(t)}</code></li>`).join('')}</ul><p>İzinli: ${m.roles.map(r=>`<span class="chip">${esc(r)}</span>`).join(' ')}</p><div class="form-actions">${btn('Kapat','close','','close')}</div></div>`)},
'mcp-toggle'(b){const m=state.mcp.find(x=>x.id===b.dataset.id);if(!m)return;m.status=m.status==='Aktif'?'Devre dışı':'Aktif';done(`${m.name}: ${m.status}.`,`MCP sunucusu ${m.status.toLocaleLowerCase('tr')}: ${m.name}`)},
'mcp-remove'(b){const m=state.mcp.find(x=>x.id===b.dataset.id);if(!m)return;state.mcp=state.mcp.filter(x=>x!==m);done(`${m.name} silindi.`,`MCP sunucusu silindi: ${m.name}`)},
'token-new'(){if($('#modal').open)closeDialog();tokenNewDialog()},
'token-revoke'(b){const t=state.tokens.find(x=>x.id===b.dataset.id);if(!t)return;t.revoked=true;done('Token iptal edildi.',`Erişim tokenı iptal edildi: ${t.name}`)},
'hook-rotate'(b){const w=state.webhooksIn.find(x=>x.id===b.dataset.id);if(!w)return;w.secret='whsec_'+randomToken().slice(4,20);done('Webhook sırrı döndürüldü; eski sır 24 saat geçerli.',`Webhook sırrı döndürüldü: ${w.path}`)},
'hook-test'(b){const w=state.webhooksOut.find(x=>x.id===b.dataset.id);if(!w)return;emit('webhook.test',`webhook:${w.id}`);done(w.active?`Test gönderildi → 200 OK (${w.event})`:'Webhook pasif; önce etkinleştir.',`Giden webhook test edildi: ${w.event}`,false)},
'hook-out-add'(){hookOutDialog()},
// settings
'sla-add'(){state.settings.structure.taskTypes.push({name:'Yeni görev türü',sla:48});done('Görev türü eklendi; adı düzenle.','Görev türü eklendi.')},
'sla-remove'(b){const t=state.settings.structure.taskTypes.splice(Number(b.dataset.id),1)[0];done('Görev türü silindi.',`Görev türü silindi: ${t?.name}`)},
'chip-remove'(b){const arr=getPath(state,b.dataset.path);if(!Array.isArray(arr))return;setPath(state,b.dataset.path,arr.filter(x=>x!==b.dataset.id));done('Kaldırıldı.',`Liste güncellendi (${b.dataset.path.split('.').at(-1)}): ${b.dataset.id} kaldırıldı`)},
toggle(b){const v=b.getAttribute('aria-checked')!=='true';setPath(state,b.dataset.path,v);b.setAttribute('aria-checked',v);log(`${b.getAttribute('aria-label')}: ${v?'açık':'kapalı'}`);toast(`${b.getAttribute('aria-label')} ${v?'açıldı':'kapatıldı'}.`);if(b.dataset.rerender!==undefined)render()},
'ai-test'(){state.runs.unshift({id:'r'+Date.now(),agent:'Test',trigger:'manual:model-test',model:state.settings.ai.model,tokens:420,cost:0.01,status:'Başarılı',at:now()});done(`${state.settings.ai.model} yanıt verdi · 812 ms (simülasyon).`,`Model testi: ${state.settings.ai.model}`,false)},
'prompt-log'(){openDialog('Prompt değişiklik günlüğü',`<div class="dialog-body"><ul class="meeting-list"><li>${ic('check')}<span><strong>v2026.10.3</strong> · 11.10 · CFO runway hesabına kur varsayımı eklendi.</span></li><li>${ic('check')}<span><strong>v2026.10.2</strong> · 04.10 · İkiz teklif şablonuna “risk” alanı.</span></li><li>${ic('check')}<span><strong>v2026.10.1</strong> · 01.10 · Kurul kararı formatı: aksiyon / neden şimdi / risk / önerilen.</span></li></ul><div class="form-actions">${btn('Kapat','close','','close')}</div></div>`)},
'backup-verify'(){const d=state.settings.data;d.verifyOk=true;d.backupVerified=now();const cto=state.board.agents.find(a=>a.id==='cto');cto.health='GREEN';cto.headline='Yedek doğrulandı; geri yükleme testi başarılı.';emit('backup.verified','backup:minio-s3','user:BY');done('Yedek doğrulandı: 2,1 TB · geri yükleme testi başarılı.','MinIO → S3 yedeği doğrulandı.')},
// profile
'profile-approve'(){const p=profile();p.twin.approvedAt=new Date().toLocaleDateString('tr-TR');const tw=state.twins.find(t=>t.id===p.id);if(tw)tw.approvedAt=p.twin.approvedAt;emit('twin.profile.approved',`twin:${p.id}`,`user:${p.id}`);done('Profil onaylandı; ikiz güncel veriyle teklif verebilir.',`İkiz profili onaylandı: ${p.name}`)},
'my-int'(b){const p=profile();const k=b.dataset.id;p.integrations[k]=!p.integrations[k];done(p.integrations[k]?'Hesap bağlandı.':'Bağlantı kesildi.',`Kişisel entegrasyon ${p.integrations[k]?'bağlandı':'kesildi'}: ${k} (${p.name})`)},
'session-end'(b){const p=profile();p.security.sessions=p.security.sessions.filter(s=>s.id!==b.dataset.id);done('Oturum kapatıldı.',`Oturum kapatıldı: ${p.name}`)},
password(){openDialog('Şifreyi değiştir',`<form class="dialog-body" id="password-form"><div class="form-grid"><label class="form-field full">Mevcut şifre<input type="password" name="old" required autocomplete="current-password"></label><label class="form-field">Yeni şifre<input type="password" name="new" required minlength="12" autocomplete="new-password"></label><label class="form-field">Tekrar<input type="password" name="new2" required minlength="12" autocomplete="new-password"></label></div><p>En az 12 karakter. Prototipte şifre saklanmaz.</p><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Güncelle ${ic('check')}</button></div></form>`)}

});

Object.assign(forms,{
'tender-form'(get){if(!get('brief'))return;tender=simulateBids(get('brief'),get('due'),get('project'));emit('tender.opened',`tender:${tender.id}`);tender.bids.forEach(b=>emit('twin.bid.created',`tender:${tender.id}`,`twin:${b.twin.id}`));log(`İhale açıldı ${tender.id}: ${tender.bids.length} ikiz teklif verdi.`);closeDialog();tenderResults();toast(`${tender.bids.length} ikiz teklif verdi.`)},
'mcp-form'(get,data){if(!get('name')||!get('url'))return;const roles=data.getAll('roles').map(String);state.mcp.push({id:'m'+Date.now(),name:get('name'),url:get('url'),auth:get('auth'),tools:mcpDraftTools||discoverTools(get('url')),status:'Aktif',roles});emit('mcp.server.added',`mcp:${get('name')}`);log(`MCP sunucusu eklendi: ${get('name')} (${roles.length} rol izinli)`);closeDialog();render();toast('MCP sunucusu eklendi.')},
'token-form'(get){if(!get('name'))return;const tok=randomToken();state.tokens.unshift({id:'k'+Date.now(),name:get('name'),scope:get('scope'),created:new Date().toLocaleDateString('tr-TR'),lastUsed:'—',revoked:false});log(`Erişim tokenı oluşturuldu: ${get('name')} (${get('scope')}, ${get('expiry')})`);closeDialog();render();openDialog('Token oluşturuldu',`<div class="dialog-body"><p>Bu token yalnızca şimdi gösterilir. Güvenli bir yere kaydet.</p><div class="token-box">${tok}</div><p class="small muted">Kapsam: ${esc(get('scope'))} · ${esc(get('expiry'))}</p><div class="form-actions">${btn('Kopyala','copy','','copy',`data-id="${tok}"`)}${btn('Kaydettim, kapat','close','primary','check')}</div></div>`)},
'hook-form'(get){if(!get('url'))return;state.webhooksOut.push({id:'o'+Date.now(),event:get('event'),url:get('url'),active:true});log(`Giden webhook eklendi: ${get('event')} → ${get('url')}`);closeDialog();render();toast('Giden webhook eklendi.')},
'password-form'(get,data,f){if(get('new')!==get('new2')){f.elements.new2.setCustomValidity('Şifreler eşleşmiyor.');f.elements.new2.reportValidity();f.elements.new2.oninput=()=>f.elements.new2.setCustomValidity('');return}log(`Şifre değiştirildi: ${profile().name}`);closeDialog();toast('Şifre güncellendi (simülasyon).')}
});
